/* Blackboard lessons for the functions cheat sheet: one lesson per card (and per row of the transformations table).
   Every lesson draws its graphs. Texts: 'en|fr|es|ja|zh'. */
(function () {
  const R = String.raw;
  const IDEA = 'The idea|L’idée|La idea|考え方|思路', EX = 'Worked example|Exemple résolu|Ejemplo resuelto|例題|例题', YOUR = 'Your turn|À vous|Te toca|やってみよう|轮到你了';
  const TRY = 'Work it out on paper, type the answer (a fraction or a decimal) and check it. Each hint writes the next line of the solution on the board.|Faites le calcul sur papier, tapez la réponse (fraction ou décimal) et vérifiez. Chaque indice écrit la ligne suivante de la solution au tableau.|Hazlo en papel, escribe la respuesta (fracción o decimal) y compruébala. Cada pista escribe en la pizarra la siguiente línea de la solución.|紙で計算し、答え（分数か小数）を入力して確かめましょう。ヒントごとに解答が 1 行ずつ黒板に書かれます。|先在纸上算，输入答案（分数或小数）并检查。每次提示会在黑板上写出解答的下一行。';
  const F = (tex, o = {}) => ['w', R`\displaystyle ` + tex, Object.assign({ s: 26 }, o)];
  const Y = (tex, o = {}) => F(tex, Object.assign({ c: 'y' }, o));
  const W = (txt, o = {}) => ['t', txt, Object.assign({ s: 18, c: 'b' }, o)];
  const H = name => ['t', name, { head: true, s: 16, c: 'y' }];
  const Z = (x, y) => [x, y, 0];
  // give a group of scene items quick, staggered delays (the default is 300 ms per item, too slow for grids)
  const SEQ = (items, d0 = 200, step = 40) => items.map((a, i) => { const o = a[a.length - 1]; if (o && typeof o === 'object' && !Array.isArray(o)) o.d = d0 + i * step; return a; });
  const S2 = (c, r, axes = false) => ['3d', { flat: true, axes, c: [c[0], c[1], 0], r }];
  const CI = (o, r, c, fill = 0.16) => ['circ3', Z(...o), [0, 0, 1], r, { c, fill }];
  const LB = (p, t, c = 'y', size) => ['lab3', Z(...p), t, Object.assign({ c }, size ? { size } : {})];
  const SG = (p, q, c = 'chalk', o = {}) => ['seg', Z(...p), Z(...q), Object.assign({ c }, o)];
  const PT = (p, lab, c = 'y', o = {}) => ['pt3', Z(...p), lab || '', Object.assign({ c }, o)];
  const RECT = (x0, y0, x1, y1, c = 'b', fill = 0.3) => ['poly3', [Z(x0, y0), Z(x1, y0), Z(x1, y1), Z(x0, y1)], { c, fill }];
  // a Venn diagram of A and B inside the universe
  const VENN = (la = 'A', lb = 'B', extra = []) => [S2([0, 0], 2.2), ...SEQ([RECT(-2.4, -1.6, 2.4, 1.6, 'chalk', 0.03), CI([-0.6, 0], 1.1, 'b'), CI([0.6, 0], 1.1, 'p'), LB([-1.3, 1.1], la, 'b'), LB([1.2, 1.1], lb, 'p'), LB([-2.2, 1.35], 'Ω', 'chalk'), ...extra], 200, 160)];
  // a two-level tree: first branch probability p (labels a, ā), then q1 / q2 for the event on each branch
  const TREE = (p, q1, q2, la, lb) => [S2([1.5, 0], 2.2), ...SEQ([
    SG([0, 0], [1.5, 1.2], 'b'), SG([0, 0], [1.5, -1.2], 'b'), SG([1.5, 1.2], [3, 1.8], 'y'), SG([1.5, 1.2], [3, 0.6], 'chalk'), SG([1.5, -1.2], [3, -0.6], 'y'), SG([1.5, -1.2], [3, -1.8], 'chalk'),
    LB([0.45, 0.85], p, 'b'), LB([0.45, -1.05], '1 − ' + p, 'b'), LB([1.5, 1.4], la[0], 'b'), LB([1.5, -1.0], la[1], 'b'),
    LB([2.0, 1.75], q1, 'y'), LB([2.0, -0.55], q2, 'y'), LB([3.1, 1.8], lb[0], 'y'), LB([3.1, 0.6], lb[1], 'chalk'), LB([3.1, -0.6], lb[0], 'y'), LB([3.1, -1.8], lb[1], 'chalk')], 200, 90)];
  // a bar chart: probabilities p[k] at x = k0 + k (height scaled by s)
  const BARS = (ps, k0 = 0, s = 1, c = 'b', hi = -1) => SEQ(ps.map((p, k) => RECT(k0 + k - 0.38, 0, k0 + k + 0.38, p * s, k === hi ? 'y' : c, k === hi ? 0.55 : 0.3)), 200, 70);
  const AX = (xw, yw) => ['ax', { xw, yw }], P = (eq, c = 'y', o = {}) => ['p', 'y=' + eq, Object.assign({ c }, o)], SH = (a, b) => ['sh', a, b];
  const N01 = 'e^(-x^2/2)/sqrt(2pi)';
  const L = {};
  const lesson = (key, head, idea, ex, your) => {
    L[key] = [{ t: IDEA, s: idea.s, a: [H(head), ...idea.a] }, { t: EX, s: ex.s, a: [['clr'], H(head), ...ex.a] },
      { t: YOUR, s: your.s || TRY, a: [['clr'], H(head), ...(your.a || [])], ex: your.ex }];
  };
  const C = (a, b) => { let r = 1; for (let k = 1; k <= b; k++) r = r * (a - b + k) / k; return r; };
  const binom = (n, p) => [...Array(n + 1)].map((_, k) => C(n, k) * p ** k * (1 - p) ** (n - k));

  const VL = (x, y0, y1, c = 'p') => ['ln', x, y0, x, y1, { c, dash: true }];   // a vertical dashed line on the graph
  const D = (eq, c = 'b') => P(eq, c, { dash: true });
  const TRY_E = 'Type an expression in x (for example 2x^2 + 3 or sqrt(x + 1)) and check it. Each hint writes the next line of the solution.|Tapez une expression en x (par exemple 2x^2 + 3 ou sqrt(x + 1)) et vérifiez. Chaque indice écrit la ligne suivante de la solution.|Escribe una expresión en x (por ejemplo 2x^2 + 3 o sqrt(x + 1)) y compruébala. Cada pista escribe la siguiente línea de la solución.|x の式（例：2x^2 + 3、sqrt(x + 1)）を入力して確かめよう。ヒントごとに解答が 1 行ずつ書かれます。|输入关于 x 的式子（如 2x^2 + 3 或 sqrt(x + 1)）并检查。每次提示写出解答的下一行。';
  const TRY_R = 'Type all the values separated by ; in any order (for example 2; -3) and check. Each hint writes the next line of the solution.|Tapez toutes les valeurs séparées par ; dans n’importe quel ordre (par exemple 2; -3) et vérifiez. Chaque indice écrit la ligne suivante.|Escribe todos los valores separados por ; en cualquier orden (por ejemplo 2; -3) y comprueba. Cada pista escribe la siguiente línea.|すべての値を ; で区切って順不同で入力（例：2; -3）して確かめよう。ヒントごとに解答が 1 行ずつ書かれます。|输入所有值，用 ; 分隔，顺序不限（如 2; -3），并检查。每次提示写出下一行。';

  // =============================== Domain and range ===============================
  lesson('Domain and range/Fractions', 'Domain of a fraction|Domaine d’une fraction|Dominio de una fracción|分数関数の定義域|分式的定义域',
    { s: R`You cannot divide by zero, so remove every $x$ that makes the denominator vanish. Solve $q(x) = 0$ and exclude those values; on the graph they are vertical asymptotes (or holes).|On ne divise pas par zéro : on retire tous les $x$ qui annulent le dénominateur. On résout $q(x) = 0$ et on exclut ces valeurs ; sur le graphe ce sont des asymptotes verticales (ou des trous).|No se puede dividir entre cero: quita todos los $x$ que anulan el denominador. Resuelve $q(x) = 0$ y excluye esos valores; en la gráfica son asíntotas verticales (o huecos).|0 では割れないので、分母を 0 にする $x$ を除く。$q(x) = 0$ を解いてその値を除外（グラフでは垂直漸近線や穴）。|不能除以零：去掉使分母为零的 $x$。解 $q(x) = 0$ 并排除这些值；在图像上是竖直渐近线（或空洞）。`,
      a: [Y(R`\frac{p(x)}{q(x)}:\quad q(x) \ne 0`, { s: 30 }), AX([-5, 5], [-4, 4]), P('1/(x^2-4)'), VL(-2, -4, 4), VL(2, -4, 4)] },
    { s: R`$f(x) = \tfrac{x + 1}{x^2 - 4}$: $x^2 - 4 = 0$ at $x = \pm 2$, so the domain is $\mathbb R \setminus \{-2, 2\}$.|$f(x) = \tfrac{x + 1}{x^2 - 4}$ : $x^2 - 4 = 0$ pour $x = \pm 2$, donc le domaine est $\mathbb R \setminus \{-2, 2\}$.|$f(x) = \tfrac{x + 1}{x^2 - 4}$: $x^2 - 4 = 0$ en $x = \pm 2$, así que el dominio es $\mathbb R \setminus \{-2, 2\}$.|$x = \pm 2$ を除く。|去掉 $x = \pm 2$。`,
      a: [F(R`x^2 - 4 = 0 \iff x = \pm 2`), Y(R`D = \mathbb R \setminus \{-2,\ 2\}`), AX([-5, 5], [-5, 5]), P('(x+1)/(x^2-4)'), VL(-2, -5, 5), VL(2, -5, 5)] },
    { s: TRY_R, a: [F(R`f(x) = \frac{1}{x^2 - 5x + 6}`)],
      ex: { k: 'roots', v: [2, 3], q: R`Which values of $x$ are excluded from the domain of $f(x) = \dfrac{1}{x^2 - 5x + 6}$?|Quelles valeurs de $x$ sont exclues du domaine de $f(x) = \dfrac{1}{x^2 - 5x + 6}$ ?|¿Qué valores de $x$ se excluyen del dominio de $f(x) = \dfrac{1}{x^2 - 5x + 6}$?|$f(x) = \dfrac{1}{x^2 - 5x + 6}$ の定義域から除かれる $x$ は？|$f(x) = \dfrac{1}{x^2 - 5x + 6}$ 的定义域要排除哪些 $x$？`,
        sol: [R`x^2 - 5x + 6 = (x - 2)(x - 3)`, R`x \ne 2,\ x \ne 3`] } });

  lesson('Domain and range/Even roots', 'Domain of an even root|Domaine d’une racine paire|Dominio de una raíz par|偶数乗根の定義域|偶次根式的定义域',
    { s: R`A square root (or 4th, 6th… root) of a negative number is not real, so the inside must be $\ge 0$. Solve that inequality; the graph starts at the point where the inside is zero. Odd roots ($\sqrt[3]{\ }$) accept every real number.|La racine carrée (ou 4e, 6e…) d’un nombre négatif n’est pas réelle : l’intérieur doit être $\ge 0$. On résout cette inéquation ; le graphe commence là où l’intérieur s’annule. Les racines impaires ($\sqrt[3]{\ }$) acceptent tout réel.|La raíz cuadrada (o cuarta, sexta…) de un negativo no es real, así que el interior debe ser $\ge 0$. Resuelve esa inecuación; la gráfica empieza donde el interior vale cero. Las raíces impares ($\sqrt[3]{\ }$) admiten cualquier real.|負の数の平方根（4 乗根…）は実数でないので中身 $\ge 0$。その不等式を解く。グラフは中身が 0 の点から始まる。奇数乗根はすべての実数で定義。|负数的平方根（四次根……）不是实数，所以根号内 $\ge 0$。解这个不等式；图像从根号内为零处开始。奇次根（$\sqrt[3]{\ }$）对所有实数有定义。`,
      a: [Y(R`\sqrt[2k]{g(x)}:\quad g(x) \ge 0`, { s: 30 }), AX([-4, 6], [-1, 4]), P('sqrt(x+2)'), ['pt', -2, 0, 'x = −2', { c: 'o' }]] },
    { s: R`$f(x) = \sqrt{6 - 2x}$: $6 - 2x \ge 0 \iff x \le 3$, so $D = (-\infty, 3]$. The graph ends at $(3, 0)$.|$f(x) = \sqrt{6 - 2x}$ : $6 - 2x \ge 0 \iff x \le 3$, donc $D = ]-\infty, 3]$.|$f(x) = \sqrt{6 - 2x}$: $6 - 2x \ge 0 \iff x \le 3$, así que $D = (-\infty, 3]$.|$x \le 3$。|$x \le 3$。`,
      a: [F(R`6 - 2x \ge 0 \iff x \le 3`), Y(R`D = (-\infty,\ 3]`), AX([-4, 5], [-1, 4]), P('sqrt(6-2x)'), ['pt', 3, 0, '(3, 0)', { c: 'o' }]] },
    { a: [F(R`f(x) = \sqrt{2x + 8}`)],
      ex: { k: 'val', v: '-4', q: R`What is the smallest $x$ in the domain of $f(x) = \sqrt{2x + 8}$?|Quel est le plus petit $x$ du domaine de $f(x) = \sqrt{2x + 8}$ ?|¿Cuál es el menor $x$ del dominio de $f(x) = \sqrt{2x + 8}$?|$f(x) = \sqrt{2x + 8}$ の定義域で最小の $x$ は？|$f(x) = \sqrt{2x + 8}$ 定义域中最小的 $x$ 是多少？`, sol: [R`2x + 8 \ge 0`, R`x \ge -4`] } });

  lesson('Domain and range/Logarithms', 'Domain of a logarithm|Domaine d’un logarithme|Dominio de un logaritmo|対数関数の定義域|对数函数的定义域',
    { s: R`A logarithm only accepts positive numbers — strictly: $\log 0$ is undefined too. So require the inside $> 0$; at the boundary the graph has a vertical asymptote going down to $-\infty$.|Un logarithme n’accepte que des nombres strictement positifs : $\log 0$ n’existe pas non plus. On exige donc l’intérieur $> 0$ ; à la frontière le graphe a une asymptote verticale vers $-\infty$.|Un logaritmo solo acepta números estrictamente positivos: $\log 0$ tampoco existe. Exige que el interior sea $> 0$; en la frontera la gráfica tiene una asíntota vertical hacia $-\infty$.|対数は正の数（0 は不可）のみ。中身 $> 0$ を要求し、境界でグラフは $-\infty$ へ向かう垂直漸近線をもつ。|对数只接受严格正数：$\log 0$ 也无定义。要求真数 $> 0$；在边界处图像有趋向 $-\infty$ 的竖直渐近线。`,
      a: [Y(R`\log_a g(x):\quad g(x) > 0`, { s: 30 }), AX([-1, 9], [-4, 3]), P('ln(x-3)'), VL(3, -4, 3)] },
    { s: R`$f(x) = \ln(x - 3)$: $x - 3 > 0 \iff x > 3$. For $\ln(9 - x^2)$ you need $x^2 < 9$, i.e. $-3 < x < 3$.|$f(x) = \ln(x - 3)$ : $x > 3$. Pour $\ln(9 - x^2)$ il faut $x^2 < 9$, soit $-3 < x < 3$.|$f(x) = \ln(x - 3)$: $x > 3$. Para $\ln(9 - x^2)$ hace falta $x^2 < 9$, es decir $-3 < x < 3$.|$\ln(9 - x^2)$ は $-3 < x < 3$。|$\ln(9 - x^2)$：$-3 < x < 3$。`,
      a: [F(R`\ln(x - 3):\ x > 3`), Y(R`\ln(9 - x^2):\ -3 < x < 3`), AX([-4, 4], [-4, 3]), P('ln(9-x^2)'), VL(-3, -4, 3), VL(3, -4, 3)] },
    { s: TRY_R, a: [F(R`f(x) = \ln(x^2 - 4x)`)],
      ex: { k: 'roots', v: [0, 4], q: R`The domain of $f(x) = \ln(x^2 - 4x)$ is $x < a$ or $x > b$. Give $a$ and $b$.|Le domaine de $f(x) = \ln(x^2 - 4x)$ est $x < a$ ou $x > b$. Donnez $a$ et $b$.|El dominio de $f(x) = \ln(x^2 - 4x)$ es $x < a$ o $x > b$. Da $a$ y $b$.|$f(x) = \ln(x^2 - 4x)$ の定義域は $x < a$ または $x > b$。$a$, $b$ を答えよ。|$f(x) = \ln(x^2 - 4x)$ 的定义域为 $x < a$ 或 $x > b$，求 $a$、$b$。`,
        sol: [R`x^2 - 4x = x(x - 4) > 0`, R`x < 0\ \text{or}\ x > 4`] } });

  lesson('Domain and range/tan and the inverse functions', 'Domains of tan, arcsin, arccos|Domaines de tan, arcsin, arccos|Dominios de tan, arcsen, arccos|tan, arcsin, arccos の定義域|tan、arcsin、arccos 的定义域',
    { s: R`$\tan x = \tfrac{\sin x}{\cos x}$ is a fraction, undefined where $\cos x = 0$. $\arcsin$ and $\arccos$ undo $\sin$ and $\cos$, whose values lie in $[-1, 1]$ — so only those numbers can go in.|$\tan x = \tfrac{\sin x}{\cos x}$ est une fraction, non définie quand $\cos x = 0$. $\arcsin$ et $\arccos$ défont $\sin$ et $\cos$, dont les valeurs sont dans $[-1, 1]$ : seuls ces nombres peuvent y entrer.|$\tan x = \tfrac{\sin x}{\cos x}$ es una fracción, no definida donde $\cos x = 0$. $\arcsin$ y $\arccos$ deshacen $\sin$ y $\cos$, cuyos valores están en $[-1, 1]$: solo esos números pueden entrar.|$\tan x = \tfrac{\sin x}{\cos x}$ は分数なので $\cos x = 0$ で定義されない。$\arcsin$, $\arccos$ は値が $[-1, 1]$ の $\sin$, $\cos$ の逆なので、入れられるのはその範囲だけ。|$\tan x = \tfrac{\sin x}{\cos x}$ 是分式，$\cos x = 0$ 处无定义。$\arcsin$、$\arccos$ 是 $\sin$、$\cos$ 的反函数，后者取值在 $[-1, 1]$，只有这些数能代入。`,
      a: [Y(R`\tan x:\ x \ne \tfrac\pi2 + k\pi,\qquad \arcsin x,\ \arccos x:\ \lvert x\rvert \le 1`, { s: 20 }), AX([-1.5, 1.5], [-2, 2]), P('asin(x)'), VL(-1, -2, 2, 'g'), VL(1, -2, 2, 'g')] },
    { s: R`$f(x) = \arcsin(2x - 1)$: $-1 \le 2x - 1 \le 1 \iff 0 \le 2x \le 2 \iff 0 \le x \le 1$.|$f(x) = \arcsin(2x - 1)$ : $-1 \le 2x - 1 \le 1 \iff 0 \le x \le 1$.|$f(x) = \arcsin(2x - 1)$: $-1 \le 2x - 1 \le 1 \iff 0 \le x \le 1$.|$0 \le x \le 1$。|$0 \le x \le 1$。`,
      a: [F(R`-1 \le 2x - 1 \le 1`), Y(R`0 \le x \le 1`), AX([-0.6, 1.6], [-2, 2]), P('asin(2x-1)')] },
    { s: TRY_R, a: [F(R`f(x) = \arcsin(x - 2)`)],
      ex: { k: 'roots', v: [1, 3], q: R`The domain of $f(x) = \arcsin(x - 2)$ is $[a, b]$. Give $a$ and $b$.|Le domaine de $f(x) = \arcsin(x - 2)$ est $[a, b]$. Donnez $a$ et $b$.|El dominio de $f(x) = \arcsin(x - 2)$ es $[a, b]$. Da $a$ y $b$.|$f(x) = \arcsin(x - 2)$ の定義域は $[a, b]$。$a$, $b$ を答えよ。|$f(x) = \arcsin(x - 2)$ 的定义域为 $[a, b]$，求 $a$、$b$。`, sol: [R`-1 \le x - 2 \le 1`, R`1 \le x \le 3`] } });

  lesson('Domain and range/Ranges to remember', 'Ranges to remember|Images à connaître|Recorridos que conviene recordar|覚えておく値域|需记住的值域',
    { s: R`Many ranges come from a few facts: $e^x$ is always positive, squares are never negative, $\sin$ and $\cos$ stay between $-1$ and $1$, and $x + \tfrac1x \ge 2$ for $x > 0$ (equality at $x = 1$). Build the range of a formula from these bounds.|Beaucoup d’images découlent de quelques faits : $e^x$ est toujours positif, un carré n’est jamais négatif, $\sin$ et $\cos$ restent entre $-1$ et $1$, et $x + \tfrac1x \ge 2$ pour $x > 0$ (égalité en $x = 1$). On construit l’image d’une formule à partir de ces bornes.|Muchos recorridos salen de unos pocos hechos: $e^x$ siempre es positivo, los cuadrados nunca son negativos, $\sin$ y $\cos$ están entre $-1$ y $1$, y $x + \tfrac1x \ge 2$ para $x > 0$ (igualdad en $x = 1$). Construye el recorrido de una fórmula a partir de estas cotas.|多くの値域は少しの事実から：$e^x > 0$、2 乗は負でない、$\sin$, $\cos$ は $-1$〜$1$、$x > 0$ なら $x + \tfrac1x \ge 2$（$x = 1$ で等号）。これらの範囲から式の値域を組み立てる。|许多值域来自几个事实：$e^x$ 恒正，平方非负，$\sin$、$\cos$ 在 $-1$ 到 $1$ 之间，$x > 0$ 时 $x + \tfrac1x \ge 2$（$x = 1$ 时取等）。由这些界构造式子的值域。`,
      a: [Y(R`e^x > 0,\quad x^2 \ge 0,\quad -1 \le \sin x \le 1,\quad x + \tfrac1x \ge 2`, { s: 20 }), AX([0, 5], [0, 6]), P('x+1/x'), ['pt', 1, 2, '(1, 2)', { c: 'o' }]] },
    { s: R`$f(x) = 3 + 2\sin x$: from $-1 \le \sin x \le 1$, multiply by 2 and add 3: $1 \le f(x) \le 5$.|$f(x) = 3 + 2\sin x$ : de $-1 \le \sin x \le 1$, on multiplie par 2 et on ajoute 3 : $1 \le f(x) \le 5$.|$f(x) = 3 + 2\sin x$: de $-1 \le \sin x \le 1$, multiplica por 2 y suma 3: $1 \le f(x) \le 5$.|$1 \le 3 + 2\sin x \le 5$。|$1 \le 3 + 2\sin x \le 5$。`,
      a: [F(R`-2 \le 2\sin x \le 2`), Y(R`1 \le 3 + 2\sin x \le 5`), AX([-7, 7], [-1, 6]), P('3+2sin(x)'), D('1', 'g'), D('5', 'g')] },
    { a: [F(R`f(x) = 4x + \frac1x,\quad x > 0`)],
      ex: { k: 'val', v: '4', q: R`Find the minimum value of $f(x) = 4x + \tfrac1x$ for $x > 0$.|Trouvez la valeur minimale de $f(x) = 4x + \tfrac1x$ pour $x > 0$.|Halla el valor mínimo de $f(x) = 4x + \tfrac1x$ para $x > 0$.|$x > 0$ で $f(x) = 4x + \tfrac1x$ の最小値を求めよ。|求 $x > 0$ 时 $f(x) = 4x + \tfrac1x$ 的最小值。`,
        sol: [R`4x + \frac1x = 2\left(2x + \frac{1}{2x}\right)`, R`\ge 2\cdot 2 = 4\quad (x = \tfrac12)`] } });

  lesson('Domain and range/Range by solving for x', 'Range by solving for x|Image en résolvant en x|Recorrido despejando x|x について解いて値域|解出 x 求值域',
    { s: R`A value $y$ is in the range exactly when $y = f(x)$ has a solution $x$ in the domain. So solve for $x$ in terms of $y$ and see which $y$ are allowed — those form the range.|Une valeur $y$ est dans l’image exactement quand $y = f(x)$ a une solution $x$ dans le domaine. On résout donc en $x$ en fonction de $y$ et on regarde quels $y$ sont permis : ils forment l’image.|Un valor $y$ está en el recorrido justo cuando $y = f(x)$ tiene solución $x$ en el dominio. Así que despeja $x$ en función de $y$ y mira qué $y$ se permiten: forman el recorrido.|$y$ が値域にあるのは $y = f(x)$ が定義域内に解 $x$ をもつときちょうど。$x$ を $y$ で表し、許される $y$ が値域。|$y$ 在值域中当且仅当 $y = f(x)$ 在定义域内有解。所以用 $y$ 表示 $x$，看哪些 $y$ 被允许——它们构成值域。`,
      a: [Y(R`y = f(x)\ \Rightarrow\ x = g(y),\qquad f(D) = \operatorname{Dom} g`), AX([-5, 6], [-5, 8]), P('(2x+1)/(x-1)'), D('2', 'g'), VL(1, -5, 8)] },
    { s: R`$y = \tfrac{2x + 1}{x - 1}$: $y(x - 1) = 2x + 1 \Rightarrow x(y - 2) = y + 1 \Rightarrow x = \tfrac{y + 1}{y - 2}$. This works unless $y = 2$, so the range is $\mathbb R \setminus \{2\}$ — the horizontal asymptote.|$y = \tfrac{2x + 1}{x - 1}$ : $x = \tfrac{y + 1}{y - 2}$, possible sauf si $y = 2$ : l’image est $\mathbb R \setminus \{2\}$ — l’asymptote horizontale.|$y = \tfrac{2x + 1}{x - 1}$: $x = \tfrac{y + 1}{y - 2}$, posible salvo si $y = 2$: el recorrido es $\mathbb R \setminus \{2\}$, la asíntota horizontal.|$x = \tfrac{y + 1}{y - 2}$ で $y \ne 2$。|$x = \tfrac{y + 1}{y - 2}$，$y \ne 2$。`,
      a: [F(R`x(y - 2) = y + 1`), Y(R`x = \frac{y + 1}{y - 2}\ \Rightarrow\ y \ne 2`)] },
    { a: [F(R`f(x) = \frac{3x - 1}{x + 2}`), AX([-8, 5], [-6, 12]), P('(3x-1)/(x+2)'), VL(-2, -6, 12)],
      ex: { k: 'val', v: '3', q: R`Which single value is missing from the range of $f(x) = \dfrac{3x - 1}{x + 2}$?|Quelle valeur unique manque dans l’image de $f(x) = \dfrac{3x - 1}{x + 2}$ ?|¿Qué único valor falta en el recorrido de $f(x) = \dfrac{3x - 1}{x + 2}$?|$f(x) = \dfrac{3x - 1}{x + 2}$ の値域にない値は？|$f(x) = \dfrac{3x - 1}{x + 2}$ 的值域缺少哪个值？`,
        sol: [R`y(x + 2) = 3x - 1 \Rightarrow x(y - 3) = -1 - 2y`, R`x = \frac{-1 - 2y}{y - 3}\ \Rightarrow\ y \ne 3`] } });

  // =============================== Composition and inverse ===============================
  lesson('Composition and inverse/Composition', 'Composition|Composition|Composición|合成関数|复合函数',
    { s: R`$f \circ g$ means “do $g$ first, then $f$”: put $g(x)$ in place of every $x$ in $f$. The order matters — squaring then adding 1 is not the same as adding 1 then squaring.|$f \circ g$ signifie « d’abord $g$, puis $f$ » : on remplace chaque $x$ de $f$ par $g(x)$. L’ordre compte : élever au carré puis ajouter 1 n’est pas ajouter 1 puis élever au carré.|$f \circ g$ significa «primero $g$, luego $f$»: pon $g(x)$ en lugar de cada $x$ de $f$. El orden importa: elevar al cuadrado y sumar 1 no es lo mismo que sumar 1 y elevar al cuadrado.|$f \circ g$ は「先に $g$、次に $f$」：$f$ の $x$ をすべて $g(x)$ に置き換える。順序が大事（2 乗して 1 足すのと、1 足して 2 乗するのは違う）。|$f \circ g$ 表示“先做 $g$，再做 $f$”：把 $f$ 中的每个 $x$ 换成 $g(x)$。顺序重要——先平方再加 1 与先加 1 再平方不同。`,
      a: [Y(R`(f \circ g)(x) = f\big(g(x)\big),\qquad f \circ g \ne g \circ f`, { s: 24 }), AX([-3, 3], [-1, 6]), P('(x+1)^2'), P('x^2+1', 'b')] },
    { s: R`$f(x) = x^2$, $g(x) = x + 1$: $(f \circ g)(x) = (x + 1)^2$ (yellow) but $(g \circ f)(x) = x^2 + 1$ (blue). They agree only at $x = 0$.|$f(x) = x^2$, $g(x) = x + 1$ : $(f \circ g)(x) = (x + 1)^2$ (jaune) mais $(g \circ f)(x) = x^2 + 1$ (bleu). Elles ne coïncident qu’en $x = 0$.|$f(x) = x^2$, $g(x) = x + 1$: $(f \circ g)(x) = (x + 1)^2$ (amarillo) pero $(g \circ f)(x) = x^2 + 1$ (azul). Solo coinciden en $x = 0$.|$(f \circ g)(x) = (x + 1)^2$、$(g \circ f)(x) = x^2 + 1$。|$(f \circ g)(x) = (x + 1)^2$，$(g \circ f)(x) = x^2 + 1$。`,
      a: [F(R`f\big(g(x)\big) = (x + 1)^2`), Y(R`g\big(f(x)\big) = x^2 + 1`), AX([-3, 3], [-1, 6]), P('(x+1)^2'), P('x^2+1', 'b')] },
    { s: TRY_E, a: [F(R`f(x) = 2x + 3,\quad g(x) = x^2`)],
      ex: { k: 'expr', f: '2x^2+3', q: R`$f(x) = 2x + 3$ and $g(x) = x^2$. Find $f\big(g(x)\big)$.|$f(x) = 2x + 3$ et $g(x) = x^2$. Calculez $f\big(g(x)\big)$.|$f(x) = 2x + 3$ y $g(x) = x^2$. Halla $f\big(g(x)\big)$.|$f(x) = 2x + 3$, $g(x) = x^2$。$f\big(g(x)\big)$ を求めよ。|$f(x) = 2x + 3$，$g(x) = x^2$，求 $f\big(g(x)\big)$。`, sol: [R`f\big(g(x)\big) = 2\,g(x) + 3`, R`= 2x^2 + 3`] } });

  lesson('Composition and inverse/Inverse function', 'The inverse function|La fonction réciproque|La función inversa|逆関数|反函数',
    { s: R`The inverse undoes $f$: if $f$ sends $x$ to $y$, then $f^{-1}$ sends $y$ back to $x$. To find it, write $y = f(x)$, solve for $x$, then rename $y$ as $x$. It exists only if $f$ never takes the same value twice (one-to-one).|La réciproque défait $f$ : si $f$ envoie $x$ sur $y$, $f^{-1}$ renvoie $y$ sur $x$. Pour la trouver, on écrit $y = f(x)$, on résout en $x$, puis on renomme $y$ en $x$. Elle n’existe que si $f$ ne prend jamais deux fois la même valeur (injective).|La inversa deshace $f$: si $f$ lleva $x$ a $y$, $f^{-1}$ devuelve $y$ a $x$. Para hallarla, escribe $y = f(x)$, despeja $x$ y renombra $y$ como $x$. Solo existe si $f$ nunca repite valor (inyectiva).|逆関数は $f$ を元に戻す：$f$ が $x$ を $y$ に送るなら $f^{-1}$ は $y$ を $x$ に戻す。$y = f(x)$ を $x$ について解き、$y$ を $x$ に書き換える。同じ値を 2 回とらない（単射）ときだけ存在。|反函数撤销 $f$：若 $f$ 把 $x$ 变为 $y$，则 $f^{-1}$ 把 $y$ 变回 $x$。求法：写 $y = f(x)$，解出 $x$，再把 $y$ 改写为 $x$。只有当 $f$ 不取重复值（单射）时才存在。`,
      a: [Y(R`y = f(x) \iff x = f^{-1}(y)`), F(R`f\big(f^{-1}(x)\big) = x`), AX([-4, 6], [-4, 6], ), P('3x-2'), P('(x+2)/3', 'b'), D('x', 'g')] },
    { s: R`$f(x) = 3x - 2$: $y = 3x - 2 \Rightarrow x = \tfrac{y + 2}{3}$, so $f^{-1}(x) = \tfrac{x + 2}{3}$. Check: $f\big(f^{-1}(x)\big) = 3\cdot\tfrac{x + 2}{3} - 2 = x$.|$f(x) = 3x - 2$ : $x = \tfrac{y + 2}{3}$, donc $f^{-1}(x) = \tfrac{x + 2}{3}$. Vérification : $f\big(f^{-1}(x)\big) = x$.|$f(x) = 3x - 2$: $x = \tfrac{y + 2}{3}$, así que $f^{-1}(x) = \tfrac{x + 2}{3}$. Comprobación: $f\big(f^{-1}(x)\big) = x$.|$f^{-1}(x) = \tfrac{x + 2}{3}$。|$f^{-1}(x) = \tfrac{x + 2}{3}$。`,
      a: [F(R`y = 3x - 2 \Rightarrow x = \frac{y + 2}{3}`), Y(R`f^{-1}(x) = \frac{x + 2}{3}`)] },
    { s: TRY_E, a: [F(R`f(x) = 5 - 2x`)],
      ex: { k: 'expr', f: '(5-x)/2', q: R`Find the inverse of $f(x) = 5 - 2x$.|Trouvez la réciproque de $f(x) = 5 - 2x$.|Halla la inversa de $f(x) = 5 - 2x$.|$f(x) = 5 - 2x$ の逆関数を求めよ。|求 $f(x) = 5 - 2x$ 的反函数。`, sol: [R`y = 5 - 2x \Rightarrow 2x = 5 - y`, R`f^{-1}(x) = \frac{5 - x}{2}`] } });

  lesson('Composition and inverse/Graph of the inverse', 'Graph of the inverse|Graphe de la réciproque|Gráfica de la inversa|逆関数のグラフ|反函数的图像',
    { s: R`Swapping $x$ and $y$ reflects every point in the line $y = x$. So the graph of $f^{-1}$ is the mirror image of the graph of $f$: $e^x$ and $\ln x$ are the classic pair, with $(0, 1)$ going to $(1, 0)$.|Échanger $x$ et $y$ fait la symétrie de chaque point par rapport à $y = x$. Le graphe de $f^{-1}$ est donc le symétrique de celui de $f$ : $e^x$ et $\ln x$ forment le couple classique, $(0, 1)$ devenant $(1, 0)$.|Intercambiar $x$ e $y$ refleja cada punto en la recta $y = x$. La gráfica de $f^{-1}$ es la imagen especular de la de $f$: $e^x$ y $\ln x$ son la pareja clásica, con $(0, 1)$ que pasa a $(1, 0)$.|$x$ と $y$ を入れ替えると各点は $y = x$ に関して対称移動。$f^{-1}$ のグラフは $f$ の鏡像：$e^x$ と $\ln x$ が典型で、$(0, 1)$ は $(1, 0)$ へ。|交换 $x$、$y$ 就是把每个点关于 $y = x$ 对称。$f^{-1}$ 的图像是 $f$ 的镜像：$e^x$ 与 $\ln x$ 是经典的一对，$(0, 1)$ 对应 $(1, 0)$。`,
      a: [Y(R`(a, b) \in f \iff (b, a) \in f^{-1}`), AX([-3, 5], [-3, 5]), P('e^x'), P('ln(x)', 'b'), D('x', 'g'), ['pt', 0, 1, '(0, 1)', { c: 'y' }], ['pt', 1, 0, '(1, 0)', { c: 'b' }]] },
    { s: R`$f(x) = x^3$ passes through $(2, 8)$, so $f^{-1}(x) = \sqrt[3]{x}$ passes through $(8, 2)$: $f^{-1}(8) = 2$.|$f(x) = x^3$ passe par $(2, 8)$, donc $f^{-1}(x) = \sqrt[3]{x}$ passe par $(8, 2)$ : $f^{-1}(8) = 2$.|$f(x) = x^3$ pasa por $(2, 8)$, así que $f^{-1}(x) = \sqrt[3]{x}$ pasa por $(8, 2)$: $f^{-1}(8) = 2$.|$(2, 8) \to (8, 2)$。|$(2, 8) \to (8, 2)$。`,
      a: [Y(R`(2, 8) \in f \Rightarrow f^{-1}(8) = 2`)] },
    { a: [F(R`f(x) = x^3 + 1`)],
      ex: { k: 'val', v: '2', q: R`$f(x) = x^3 + 1$. Find $f^{-1}(9)$.|$f(x) = x^3 + 1$. Calculez $f^{-1}(9)$.|$f(x) = x^3 + 1$. Halla $f^{-1}(9)$.|$f(x) = x^3 + 1$。$f^{-1}(9)$ を求めよ。|$f(x) = x^3 + 1$，求 $f^{-1}(9)$。`, sol: [R`x^3 + 1 = 9 \Rightarrow x^3 = 8`, R`f^{-1}(9) = 2`] } });

  lesson('Composition and inverse/Domain swaps with range', 'Domain and range swap|Domaine et image s’échangent|Dominio y recorrido se intercambian|定義域と値域の入れ替え|定义域与值域互换',
    { s: R`What goes in to $f^{-1}$ is what came out of $f$. So the domain of $f^{-1}$ is the range of $f$, and the range of $f^{-1}$ is the domain of $f$. Finding the range of $f$ first tells you where $f^{-1}$ lives.|Ce qui entre dans $f^{-1}$ est ce qui est sorti de $f$. Le domaine de $f^{-1}$ est donc l’image de $f$, et l’image de $f^{-1}$ le domaine de $f$. Trouver d’abord l’image de $f$ dit où vit $f^{-1}$.|Lo que entra en $f^{-1}$ es lo que salió de $f$. El dominio de $f^{-1}$ es el recorrido de $f$, y el recorrido de $f^{-1}$ es el dominio de $f$. Hallar primero el recorrido de $f$ dice dónde vive $f^{-1}$.|$f^{-1}$ に入るのは $f$ から出たもの。$f^{-1}$ の定義域は $f$ の値域、$f^{-1}$ の値域は $f$ の定義域。|进入 $f^{-1}$ 的就是 $f$ 输出的。所以 $f^{-1}$ 的定义域是 $f$ 的值域，$f^{-1}$ 的值域是 $f$ 的定义域。`,
      a: [Y(R`\operatorname{Dom} f^{-1} = f(D)`), AX([-1, 7], [-1, 7]), P('sqrt(x-1)+2'), P('(x-2)^2+1', 'b'), D('x', 'g')] },
    { s: R`$f(x) = \sqrt{x - 1} + 2$ has domain $x \ge 1$ and range $y \ge 2$. Its inverse $f^{-1}(x) = (x - 2)^2 + 1$ is defined for $x \ge 2$ only (blue curve, right half).|$f(x) = \sqrt{x - 1} + 2$ a pour domaine $x \ge 1$ et image $y \ge 2$. Sa réciproque $(x - 2)^2 + 1$ n’est définie que pour $x \ge 2$.|$f(x) = \sqrt{x - 1} + 2$ tiene dominio $x \ge 1$ y recorrido $y \ge 2$. Su inversa $(x - 2)^2 + 1$ solo se define para $x \ge 2$.|$f^{-1}(x) = (x - 2)^2 + 1$（$x \ge 2$）。|$f^{-1}(x) = (x - 2)^2 + 1$（$x \ge 2$）。`,
      a: [F(R`f(D) = [2, \infty)`), Y(R`f^{-1}(x) = (x - 2)^2 + 1,\ \ x \ge 2`)] },
    { a: [F(R`f(x) = e^x + 3`)],
      ex: { k: 'val', v: '3', q: R`$f(x) = e^x + 3$. The domain of $f^{-1}$ is $x > a$. Find $a$.|$f(x) = e^x + 3$. Le domaine de $f^{-1}$ est $x > a$. Trouvez $a$.|$f(x) = e^x + 3$. El dominio de $f^{-1}$ es $x > a$. Halla $a$.|$f(x) = e^x + 3$。$f^{-1}$ の定義域は $x > a$。$a$ を求めよ。|$f(x) = e^x + 3$，$f^{-1}$ 的定义域为 $x > a$，求 $a$。`, sol: [R`e^x > 0 \Rightarrow f(x) > 3`, R`\operatorname{Dom} f^{-1} = (3, \infty)`] } });

  // =============================== Symmetry, periodicity, monotonicity ===============================
  lesson('Symmetry, periodicity, monotonicity/Even function', 'Even functions|Fonctions paires|Funciones pares|偶関数|偶函数',
    { s: R`$f$ is even if $f(-x) = f(x)$: the graph is symmetric about the $y$-axis. Only even powers of $x$, $\cos x$, $\lvert x\rvert$… To use it: knowing $f$ for $x \ge 0$ gives it everywhere.|$f$ est paire si $f(-x) = f(x)$ : le graphe est symétrique par rapport à l’axe des $y$. Puissances paires de $x$, $\cos x$, $\lvert x\rvert$… En pratique : connaître $f$ pour $x \ge 0$ la donne partout.|$f$ es par si $f(-x) = f(x)$: la gráfica es simétrica respecto al eje $y$. Potencias pares de $x$, $\cos x$, $\lvert x\rvert$… En la práctica: conocer $f$ para $x \ge 0$ la da en todas partes.|$f(-x) = f(x)$ なら偶関数で、グラフは $y$ 軸対称。偶数乗、$\cos x$、$\lvert x\rvert$ など。$x \ge 0$ での値がわかれば全体がわかる。|$f(-x) = f(x)$ 时 $f$ 为偶函数：图像关于 $y$ 轴对称。偶次幂、$\cos x$、$\lvert x\rvert$……知道 $x \ge 0$ 的部分就知道全部。`,
      a: [Y(R`f(-x) = f(x)`, { s: 30 }), AX([-3, 3], [-3, 4]), P('x^4-3x^2'), ['pt', -1.5, -1.6875, '', { c: 'b' }], ['pt', 1.5, -1.6875, '', { c: 'b' }]] },
    { s: R`$f(x) = x^4 - 3x^2$: $f(-x) = (-x)^4 - 3(-x)^2 = x^4 - 3x^2 = f(x)$, so it is even — the two blue points mirror each other.|$f(-x) = x^4 - 3x^2 = f(x)$ : paire — les deux points bleus sont symétriques.|$f(-x) = x^4 - 3x^2 = f(x)$: par; los dos puntos azules son simétricos.|$f(-x) = f(x)$ で偶関数。|$f(-x) = f(x)$，偶函数。`,
      a: [Y(R`f(-x) = (-x)^4 - 3(-x)^2 = f(x)`)] },
    { a: [F(R`f\ \text{even},\quad f(x) = x^2 - 2x\ \ (x \ge 0)`, { s: 22 }), AX([-4, 4], [-2, 8]), P('x^2-2abs(x)')],
      ex: { k: 'val', v: '3', q: R`$f$ is even and $f(x) = x^2 - 2x$ for $x \ge 0$. Find $f(-3)$.|$f$ est paire et $f(x) = x^2 - 2x$ pour $x \ge 0$. Calculez $f(-3)$.|$f$ es par y $f(x) = x^2 - 2x$ para $x \ge 0$. Halla $f(-3)$.|$f$ は偶関数で $x \ge 0$ のとき $f(x) = x^2 - 2x$。$f(-3)$ を求めよ。|$f$ 为偶函数，$x \ge 0$ 时 $f(x) = x^2 - 2x$，求 $f(-3)$。`, sol: [R`f(-3) = f(3)`, R`= 9 - 6 = 3`] } });

  lesson('Symmetry, periodicity, monotonicity/Odd function', 'Odd functions|Fonctions impaires|Funciones impares|奇関数|奇函数',
    { s: R`$f$ is odd if $f(-x) = -f(x)$: turning the graph half a turn about the origin leaves it unchanged. Odd powers, $\sin x$, $\tan x$… If an odd $f$ is defined at 0, then $f(0) = 0$.|$f$ est impaire si $f(-x) = -f(x)$ : un demi-tour autour de l’origine laisse le graphe inchangé. Puissances impaires, $\sin x$, $\tan x$… Si une fonction impaire est définie en 0, $f(0) = 0$.|$f$ es impar si $f(-x) = -f(x)$: medio giro alrededor del origen deja la gráfica igual. Potencias impares, $\sin x$, $\tan x$… Si una impar está definida en 0, $f(0) = 0$.|$f(-x) = -f(x)$ なら奇関数で、原点のまわりに半回転しても同じ。奇数乗、$\sin x$、$\tan x$ など。0 で定義されていれば $f(0) = 0$。|$f(-x) = -f(x)$ 时为奇函数：绕原点旋转半周图像不变。奇次幂、$\sin x$、$\tan x$……若在 0 处有定义，则 $f(0) = 0$。`,
      a: [Y(R`f(-x) = -f(x)`, { s: 30 }), AX([-3, 3], [-4, 4]), P('x^3-3x'), ['pt', -2, -2, '', { c: 'b' }], ['pt', 2, 2, '', { c: 'b' }], ['ln', -2, -2, 2, 2, { c: 'g', dash: true }]] },
    { s: R`$f(x) = x^3 - 3x$: $f(-x) = -x^3 + 3x = -f(x)$, odd. The points $(2, 2)$ and $(-2, -2)$ are symmetric through the origin.|$f(-x) = -x^3 + 3x = -f(x)$ : impaire. Les points $(2, 2)$ et $(-2, -2)$ sont symétriques par rapport à l’origine.|$f(-x) = -x^3 + 3x = -f(x)$: impar. Los puntos $(2, 2)$ y $(-2, -2)$ son simétricos respecto al origen.|$f(-x) = -f(x)$ で奇関数。|$f(-x) = -f(x)$，奇函数。`,
      a: [Y(R`f(-x) = -x^3 + 3x = -f(x)`)] },
    { a: [F(R`f\ \text{odd},\quad f(x) = x^2 + x\ \ (x > 0)`, { s: 22 })],
      ex: { k: 'val', v: '-6', q: R`$f$ is odd and $f(x) = x^2 + x$ for $x > 0$. Find $f(-2)$.|$f$ est impaire et $f(x) = x^2 + x$ pour $x > 0$. Calculez $f(-2)$.|$f$ es impar y $f(x) = x^2 + x$ para $x > 0$. Halla $f(-2)$.|$f$ は奇関数で $x > 0$ のとき $f(x) = x^2 + x$。$f(-2)$ を求めよ。|$f$ 为奇函数，$x > 0$ 时 $f(x) = x^2 + x$，求 $f(-2)$。`, sol: [R`f(-2) = -f(2)`, R`= -(4 + 2) = -6`] } });

  lesson('Symmetry, periodicity, monotonicity/Period', 'Periodic functions|Fonctions périodiques|Funciones periódicas|周期関数|周期函数',
    { s: R`A periodic graph repeats every $T$ units. Inside $f(\omega x)$ the variable runs $\omega$ times faster, so the pattern repeats $\lvert\omega\rvert$ times as often: the period is divided by $\lvert\omega\rvert$.|Un graphe périodique se répète toutes les $T$ unités. Dans $f(\omega x)$ la variable avance $\omega$ fois plus vite, donc le motif revient $\lvert\omega\rvert$ fois plus souvent : la période est divisée par $\lvert\omega\rvert$.|Una gráfica periódica se repite cada $T$ unidades. En $f(\omega x)$ la variable avanza $\omega$ veces más rápido, así que el patrón se repite $\lvert\omega\rvert$ veces más: el periodo se divide entre $\lvert\omega\rvert$.|周期的なグラフは $T$ ごとに繰り返す。$f(\omega x)$ では変数が $\omega$ 倍速く進むので、周期は $\lvert\omega\rvert$ で割られる。|周期图像每 $T$ 个单位重复。$f(\omega x)$ 中变量快 $\omega$ 倍，图案重复 $\lvert\omega\rvert$ 倍频繁：周期除以 $\lvert\omega\rvert$。`,
      a: [Y(R`f(x + T) = f(x),\qquad f(\omega x):\ \frac{T}{\lvert\omega\rvert}`), AX([-1, 7], [-1.6, 1.6]), P('sin(3x)'), P('sin(x)', 'b', { dash: true })] },
    { s: R`$\sin x$ has period $2\pi$, so $\sin(3x)$ has period $\tfrac{2\pi}{3}$: three full waves where $\sin x$ (dashed) makes one.|$\sin x$ a pour période $2\pi$, donc $\sin(3x)$ a pour période $\tfrac{2\pi}{3}$ : trois ondes là où $\sin x$ (pointillé) en fait une.|$\sin x$ tiene periodo $2\pi$, así que $\sin(3x)$ tiene periodo $\tfrac{2\pi}{3}$: tres ondas donde $\sin x$ (discontinua) hace una.|$\sin(3x)$ の周期は $\tfrac{2\pi}{3}$。|$\sin(3x)$ 的周期为 $\tfrac{2\pi}{3}$。`,
      a: [Y(R`T = \frac{2\pi}{3}`)] },
    { a: [F(R`f(x) = \cos\left(\frac{\pi x}{2}\right)`), AX([-1, 9], [-1.6, 1.6]), P('cos(pi*x/2)')],
      ex: { k: 'val', v: '4', q: R`Find the period of $f(x) = \cos\left(\tfrac{\pi x}{2}\right)$.|Trouvez la période de $f(x) = \cos\left(\tfrac{\pi x}{2}\right)$.|Halla el periodo de $f(x) = \cos\left(\tfrac{\pi x}{2}\right)$.|$f(x) = \cos\left(\tfrac{\pi x}{2}\right)$ の周期を求めよ。|求 $f(x) = \cos\left(\tfrac{\pi x}{2}\right)$ 的周期。`, sol: [R`T = \frac{2\pi}{\pi/2}`, R`= 4`] } });

  lesson('Symmetry, periodicity, monotonicity/Symmetry about a line', 'Symmetry about a vertical line|Symétrie par rapport à une droite verticale|Simetría respecto a una recta vertical|縦の直線に関する対称|关于竖直直线对称',
    { s: R`$f(a + x) = f(a - x)$ says: going $x$ to the right of $a$ or $x$ to the left gives the same height. The graph is symmetric about the vertical line $x = a$ — every parabola is, about its axis $x = -\tfrac{b}{2a}$.|$f(a + x) = f(a - x)$ dit : aller de $x$ à droite de $a$ ou de $x$ à gauche donne la même hauteur. Le graphe est symétrique par rapport à la droite $x = a$ — toute parabole l’est, par rapport à son axe $x = -\tfrac{b}{2a}$.|$f(a + x) = f(a - x)$ dice: ir $x$ a la derecha de $a$ o $x$ a la izquierda da la misma altura. La gráfica es simétrica respecto a la recta $x = a$; toda parábola lo es respecto a su eje $x = -\tfrac{b}{2a}$.|$a$ から右へ $x$ でも左へ $x$ でも同じ高さ。グラフは直線 $x = a$ に関して対称（放物線は軸 $x = -\tfrac{b}{2a}$ に関して対称）。|在 $a$ 右边 $x$ 或左边 $x$ 处高度相同。图像关于直线 $x = a$ 对称——每条抛物线都关于其轴 $x = -\tfrac{b}{2a}$ 对称。`,
      a: [Y(R`f(a + x) = f(a - x) \iff \text{axis } x = a`, { s: 24 }), AX([-1, 7], [-9, 4]), P('x^2-6x+1'), VL(3, -9, 4, 'g')] },
    { s: R`$f(x) = x^2 - 6x + 1$: $-\tfrac{b}{2a} = 3$; check $f(3 + x) = x^2 - 8 = f(3 - x)$. Symmetric about $x = 3$.|$f(x) = x^2 - 6x + 1$ : $-\tfrac{b}{2a} = 3$ ; $f(3 + x) = x^2 - 8 = f(3 - x)$.|$f(x) = x^2 - 6x + 1$: $-\tfrac{b}{2a} = 3$; $f(3 + x) = x^2 - 8 = f(3 - x)$.|軸 $x = 3$。|对称轴 $x = 3$。`,
      a: [F(R`-\frac{b}{2a} = \frac{6}{2} = 3`), Y(R`f(3 \pm x) = x^2 - 8`)] },
    { a: [F(R`f(x) = 2x^2 + 8x - 1`)],
      ex: { k: 'val', v: '-2', q: R`The graph of $f(x) = 2x^2 + 8x - 1$ is symmetric about the line $x = a$. Find $a$.|Le graphe de $f(x) = 2x^2 + 8x - 1$ est symétrique par rapport à $x = a$. Trouvez $a$.|La gráfica de $f(x) = 2x^2 + 8x - 1$ es simétrica respecto a $x = a$. Halla $a$.|$f(x) = 2x^2 + 8x - 1$ のグラフは直線 $x = a$ に関して対称。$a$ を求めよ。|$f(x) = 2x^2 + 8x - 1$ 的图像关于 $x = a$ 对称，求 $a$。`, sol: [R`a = -\frac{8}{2\cdot 2}`, R`= -2`] } });

  lesson('Symmetry, periodicity, monotonicity/Monotonic', 'Increasing and decreasing|Croissance et décroissance|Crecimiento y decrecimiento|増加と減少|单调性',
    { s: R`Increasing means: move right, go up. A function can increase on one interval and decrease on another — the turning points separate them. For differentiable functions, the sign of $f'$ decides.|Croissante signifie : on va à droite, on monte. Une fonction peut croître sur un intervalle et décroître sur un autre — les extremums les séparent. Pour une fonction dérivable, le signe de $f'$ décide.|Creciente significa: vas a la derecha y subes. Una función puede crecer en un intervalo y decrecer en otro; los extremos los separan. Si es derivable, decide el signo de $f'$.|増加：右へ行くと上がる。ある区間で増加し別の区間で減少することもあり、極値で分かれる。微分可能なら $f'$ の符号で決まる。|递增：向右走就上升。函数可在一个区间递增、另一个区间递减——极值点把它们分开。可导时由 $f'$ 的符号决定。`,
      a: [Y(R`x_1 < x_2 \Rightarrow f(x_1) < f(x_2)\quad (\nearrow)`, { s: 24 }), AX([-2, 5], [-5, 5]), P('x^2-4x'), ['pt', 2, -4, 'min', { c: 'o' }]] },
    { s: R`$f(x) = x^2 - 4x$ has its vertex at $x = 2$: decreasing on $(-\infty, 2]$, increasing on $[2, \infty)$.|$f(x) = x^2 - 4x$ a son sommet en $x = 2$ : décroissante sur $]-\infty, 2]$, croissante sur $[2, +\infty[$.|$f(x) = x^2 - 4x$ tiene el vértice en $x = 2$: decreciente en $(-\infty, 2]$, creciente en $[2, \infty)$.|頂点 $x = 2$ で減少から増加へ。|顶点 $x = 2$：先减后增。`,
      a: [F(R`f'(x) = 2x - 4`), Y(R`\searrow\ (-\infty, 2],\qquad \nearrow\ [2, \infty)`)] },
    { a: [F(R`f(x) = x^3 - 12x`), AX([-4, 4], [-20, 20]), P('x^3-12x')],
      ex: { k: 'val', v: '2', q: R`$f(x) = x^3 - 12x$ decreases on $[-a, a]$. Find $a$.|$f(x) = x^3 - 12x$ est décroissante sur $[-a, a]$. Trouvez $a$.|$f(x) = x^3 - 12x$ decrece en $[-a, a]$. Halla $a$.|$f(x) = x^3 - 12x$ は $[-a, a]$ で減少する。$a$ を求めよ。|$f(x) = x^3 - 12x$ 在 $[-a, a]$ 上递减，求 $a$。`, sol: [R`f'(x) = 3x^2 - 12 \le 0`, R`x^2 \le 4 \Rightarrow a = 2`] } });

  // =============================== Transformations of graphs (rows) ===============================
  const TR = (key, head, idea, ex, your) => lesson('Transformations of graphs/' + key, head, idea, ex, Object.assign({ s: TRY_E }, your));
  TR('f(x) + k', 'Shift up or down: f(x) + k|Translation verticale : f(x) + k|Traslación vertical: f(x) + k|上下の平行移動：f(x) + k|上下平移：f(x) + k',
    { s: R`Adding $k$ to the output raises every point by $k$ (down if $k < 0$). The shape and the $x$-positions do not change.|Ajouter $k$ à la sortie monte chaque point de $k$ (le descend si $k < 0$). La forme et les abscisses ne changent pas.|Sumar $k$ a la salida sube cada punto $k$ unidades (baja si $k < 0$). La forma y las abscisas no cambian.|出力に $k$ を足すと全点が $k$ だけ上へ（$k < 0$ なら下へ）。形と $x$ 座標は変わらない。|输出加 $k$ 使每个点上移 $k$（$k < 0$ 则下移）。形状和横坐标不变。`,
      a: [Y(R`y = f(x) + k`), AX([-3, 3], [-1, 7]), P('x^2', 'b', { dash: true }), P('x^2+3')] },
    { s: R`$y = x^2 + 3$ is the parabola $y = x^2$ lifted 3 units: its vertex moves from $(0, 0)$ to $(0, 3)$.|$y = x^2 + 3$ est la parabole $y = x^2$ montée de 3 : son sommet passe de $(0, 0)$ à $(0, 3)$.|$y = x^2 + 3$ es la parábola $y = x^2$ subida 3: su vértice pasa de $(0, 0)$ a $(0, 3)$.|頂点 $(0, 0) \to (0, 3)$。|顶点 $(0, 0) \to (0, 3)$。`,
      a: [Y(R`(0, 0) \to (0, 3)`), AX([-3, 3], [-1, 7]), P('x^2', 'b', { dash: true }), P('x^2+3'), ['pt', 0, 3, '(0, 3)', { c: 'o' }]] },
    { a: [F(R`y = x^2\ \to\ \text{down } 4`)],
      ex: { k: 'expr', f: 'x^2-4', q: R`Move the graph of $y = x^2$ down 4 units. Write the new equation $y = \dots$|Descendez le graphe de $y = x^2$ de 4 unités. Écrivez la nouvelle équation $y = \dots$|Baja la gráfica de $y = x^2$ 4 unidades. Escribe la nueva ecuación $y = \dots$|$y = x^2$ のグラフを下へ 4 移動した式 $y = \dots$ を書け。|把 $y = x^2$ 的图像下移 4 个单位，写出新方程 $y = \dots$`, sol: [R`k = -4`, R`y = x^2 - 4`] } });

  TR('f(x - h)', 'Shift right or left: f(x − h)|Translation horizontale : f(x − h)|Traslación horizontal: f(x − h)|左右の平行移動：f(x − h)|左右平移：f(x − h)',
    { s: R`Replacing $x$ by $x - h$ moves the graph $h$ units to the right — the opposite of what the minus sign suggests: the new graph reaches the old value at $x = h$ instead of at $0$.|Remplacer $x$ par $x - h$ déplace le graphe de $h$ vers la droite — contrairement à ce que suggère le signe moins : le nouveau graphe atteint l’ancienne valeur en $x = h$ au lieu de $0$.|Cambiar $x$ por $x - h$ mueve la gráfica $h$ a la derecha, al revés de lo que sugiere el signo menos: la nueva gráfica alcanza el valor antiguo en $x = h$ en vez de en $0$.|$x$ を $x - h$ にすると右へ $h$ 移動（マイナスの印象と逆）。元の $x = 0$ での値に $x = h$ で達する。|把 $x$ 换成 $x - h$ 使图像右移 $h$——与减号的直觉相反：新图像在 $x = h$ 处取到原来 $x = 0$ 处的值。`,
      a: [Y(R`y = f(x - h)`), AX([-3, 5], [-1, 6]), P('x^2', 'b', { dash: true }), P('(x-2)^2')] },
    { s: R`$y = (x - 2)^2$: the vertex moves from $0$ to $x = 2$, i.e. 2 units right. $y = (x + 1)^2$ would move 1 unit left.|$y = (x - 2)^2$ : le sommet passe de $0$ à $x = 2$, soit 2 vers la droite. $(x + 1)^2$ irait de 1 vers la gauche.|$y = (x - 2)^2$: el vértice pasa de $0$ a $x = 2$, 2 a la derecha. $(x + 1)^2$ iría 1 a la izquierda.|頂点が $x = 2$ へ（右へ 2）。|顶点移到 $x = 2$（右移 2）。`,
      a: [Y(R`(0, 0) \to (2, 0)`), AX([-3, 5], [-1, 6]), P('x^2', 'b', { dash: true }), P('(x-2)^2'), ['pt', 2, 0, '(2, 0)', { c: 'o' }]] },
    { a: [F(R`y = \sqrt x\ \to\ \text{left } 3`)],
      ex: { k: 'expr', f: 'sqrt(x+3)', q: R`Move the graph of $y = \sqrt x$ 3 units to the left. Write $y = \dots$|Déplacez le graphe de $y = \sqrt x$ de 3 unités vers la gauche. Écrivez $y = \dots$|Mueve la gráfica de $y = \sqrt x$ 3 unidades a la izquierda. Escribe $y = \dots$|$y = \sqrt x$ のグラフを左へ 3 移動した式を書け。|把 $y = \sqrt x$ 的图像左移 3 个单位，写出 $y = \dots$`, sol: [R`h = -3:\ x \to x + 3`, R`y = \sqrt{x + 3}`] } });

  TR(R`a\,f(x)`, 'Vertical stretch: a·f(x)|Dilatation verticale : a·f(x)|Dilatación vertical: a·f(x)|縦の拡大：a·f(x)|纵向伸缩：a·f(x)',
    { s: R`Multiplying the output by $a$ stretches the graph away from the $x$-axis ($a > 1$) or squashes it towards it ($0 < a < 1$). Points on the $x$-axis — the zeros — stay where they are.|Multiplier la sortie par $a$ étire le graphe loin de l’axe des $x$ ($a > 1$) ou l’écrase vers lui ($0 < a < 1$). Les points de l’axe des $x$ — les zéros — ne bougent pas.|Multiplicar la salida por $a$ estira la gráfica alejándola del eje $x$ ($a > 1$) o la aplasta hacia él ($0 < a < 1$). Los puntos del eje $x$, los ceros, no se mueven.|出力を $a$ 倍すると $x$ 軸から離れるように伸び（$a > 1$）、近づくように縮む（$0 < a < 1$）。$x$ 軸上の点（零点）は動かない。|输出乘 $a$ 使图像远离 $x$ 轴拉伸（$a > 1$）或向它压缩（$0 < a < 1$）。$x$ 轴上的点——零点——不动。`,
      a: [Y(R`y = a\,f(x)`), AX([-1, 7], [-2.5, 2.5]), P('sin(x)', 'b', { dash: true }), P('2sin(x)')] },
    { s: R`$y = 2\sin x$ has amplitude 2 instead of 1, but its zeros $0, \pi, 2\pi$ are unchanged.|$y = 2\sin x$ a une amplitude 2 au lieu de 1, mais ses zéros $0, \pi, 2\pi$ sont inchangés.|$y = 2\sin x$ tiene amplitud 2 en lugar de 1, pero sus ceros $0, \pi, 2\pi$ no cambian.|振幅 2、零点は同じ。|振幅为 2，零点不变。`,
      a: [Y(R`\max = 2,\quad \text{zeros } 0,\ \pi,\ 2\pi`)] },
    { a: [F(R`y = x^2 - 1\ \to\ \times 2\ \text{vertically}`)],
      ex: { k: 'expr', f: '2x^2-2', q: R`Stretch the graph of $y = x^2 - 1$ vertically by a factor 2. Write $y = \dots$|Dilatez verticalement le graphe de $y = x^2 - 1$ d’un facteur 2. Écrivez $y = \dots$|Dilata verticalmente la gráfica de $y = x^2 - 1$ con factor 2. Escribe $y = \dots$|$y = x^2 - 1$ のグラフを縦に 2 倍した式を書け。|把 $y = x^2 - 1$ 的图像纵向拉伸为 2 倍，写出 $y = \dots$`, sol: [R`y = 2(x^2 - 1)`, R`= 2x^2 - 2`] } });

  TR('f(bx)', 'Horizontal squeeze: f(bx)|Contraction horizontale : f(bx)|Compresión horizontal: f(bx)|横の縮小：f(bx)|横向伸缩：f(bx)',
    { s: R`Replacing $x$ by $bx$ makes everything happen $b$ times sooner: the graph is squeezed towards the $y$-axis by the factor $b$ (stretched if $0 < b < 1$). The $y$-intercept stays.|Remplacer $x$ par $bx$ fait tout arriver $b$ fois plus tôt : le graphe est contracté vers l’axe des $y$ d’un facteur $b$ (étiré si $0 < b < 1$). L’ordonnée à l’origine ne bouge pas.|Cambiar $x$ por $bx$ hace que todo ocurra $b$ veces antes: la gráfica se comprime hacia el eje $y$ por el factor $b$ (se estira si $0 < b < 1$). El corte con el eje $y$ no cambia.|$x$ を $bx$ にすると全てが $b$ 倍早く起こり、グラフは $y$ 軸へ $1/b$ に縮む（$0 < b < 1$ なら伸びる）。$y$ 切片は不変。|把 $x$ 换成 $bx$ 使一切提前 $b$ 倍发生：图像向 $y$ 轴压缩为 $1/b$（$0 < b < 1$ 时拉伸）。$y$ 轴截距不变。`,
      a: [Y(R`y = f(bx)`), AX([-1, 7], [-1.6, 1.6]), P('sin(x)', 'b', { dash: true }), P('sin(2x)')] },
    { s: R`$y = \sin(2x)$: what $\sin x$ does on $[0, 2\pi]$ now happens on $[0, \pi]$ — the period halves.|$y = \sin(2x)$ : ce que fait $\sin x$ sur $[0, 2\pi]$ se passe maintenant sur $[0, \pi]$ — la période est divisée par deux.|$y = \sin(2x)$: lo que $\sin x$ hace en $[0, 2\pi]$ ocurre ahora en $[0, \pi]$; el periodo se reduce a la mitad.|周期が半分の $\pi$ に。|周期减半为 $\pi$。`,
      a: [Y(R`T: 2\pi \to \pi`)] },
    { a: [F(R`y = x^2 - x\ \to\ \text{squeeze } \div 2`)],
      ex: { k: 'expr', f: '4x^2-2x', q: R`Squeeze the graph of $y = x^2 - x$ horizontally by a factor 2 (replace $x$ by $2x$). Write $y = \dots$|Contractez horizontalement le graphe de $y = x^2 - x$ d’un facteur 2 (remplacez $x$ par $2x$). Écrivez $y = \dots$|Comprime horizontalmente la gráfica de $y = x^2 - x$ con factor 2 (cambia $x$ por $2x$). Escribe $y = \dots$|$y = x^2 - x$ の $x$ を $2x$ にして横に縮めた式を書け。|把 $y = x^2 - x$ 中的 $x$ 换成 $2x$（横向压缩一半），写出 $y = \dots$`, sol: [R`y = (2x)^2 - 2x`, R`= 4x^2 - 2x`] } });

  TR('-f(x)', 'Mirror in the x-axis: −f(x)|Symétrie par rapport à l’axe des x : −f(x)|Simetría respecto al eje x: −f(x)|x 軸対称：−f(x)|关于 x 轴对称：−f(x)',
    { s: R`Changing the sign of every output turns the graph upside down: each point $(x, y)$ goes to $(x, -y)$. Maxima become minima.|Changer le signe de chaque sortie retourne le graphe : chaque point $(x, y)$ va en $(x, -y)$. Les maximums deviennent des minimums.|Cambiar el signo de cada salida da la vuelta a la gráfica: cada punto $(x, y)$ pasa a $(x, -y)$. Los máximos se vuelven mínimos.|出力の符号を変えるとグラフは上下反転：$(x, y) \to (x, -y)$。極大が極小に。|改变每个输出的符号使图像上下翻转：$(x, y) \to (x, -y)$。极大变极小。`,
      a: [Y(R`y = -f(x)`), AX([-2, 3], [-6, 6]), P('e^x', 'b', { dash: true }), P('-e^x')] },
    { s: R`$y = -e^x$ is the exponential flipped below the axis: it passes through $(0, -1)$ and is always negative.|$y = -e^x$ est l’exponentielle retournée sous l’axe : elle passe par $(0, -1)$ et est toujours négative.|$y = -e^x$ es la exponencial volteada bajo el eje: pasa por $(0, -1)$ y siempre es negativa.|$(0, -1)$ を通り常に負。|过 $(0, -1)$，恒为负。`,
      a: [Y(R`(0, 1) \to (0, -1)`)] },
    { a: [F(R`y = x^2 - 3x + 1`)],
      ex: { k: 'expr', f: '-x^2+3x-1', q: R`Reflect the graph of $y = x^2 - 3x + 1$ in the $x$-axis. Write $y = \dots$|Faites la symétrie du graphe de $y = x^2 - 3x + 1$ par rapport à l’axe des $x$. Écrivez $y = \dots$|Refleja la gráfica de $y = x^2 - 3x + 1$ respecto al eje $x$. Escribe $y = \dots$|$y = x^2 - 3x + 1$ を $x$ 軸に関して対称移動した式を書け。|把 $y = x^2 - 3x + 1$ 关于 $x$ 轴对称，写出 $y = \dots$`, sol: [R`y = -(x^2 - 3x + 1)`, R`= -x^2 + 3x - 1`] } });

  TR('f(-x)', 'Mirror in the y-axis: f(−x)|Symétrie par rapport à l’axe des y : f(−x)|Simetría respecto al eje y: f(−x)|y 軸対称：f(−x)|关于 y 轴对称：f(−x)',
    { s: R`Replacing $x$ by $-x$ swaps left and right: $(x, y)$ goes to $(-x, y)$. Even functions do not change; for others, every $x$ in the formula changes sign.|Remplacer $x$ par $-x$ échange gauche et droite : $(x, y)$ va en $(-x, y)$. Les fonctions paires ne changent pas ; pour les autres, chaque $x$ de la formule change de signe.|Cambiar $x$ por $-x$ intercambia izquierda y derecha: $(x, y)$ pasa a $(-x, y)$. Las funciones pares no cambian; en las demás, cada $x$ cambia de signo.|$x$ を $-x$ にすると左右が入れ替わる：$(x, y) \to (-x, y)$。偶関数は不変、他は式中の $x$ の符号がすべて変わる。|把 $x$ 换成 $-x$ 交换左右：$(x, y) \to (-x, y)$。偶函数不变；其他函数式中每个 $x$ 变号。`,
      a: [Y(R`y = f(-x)`), AX([-3, 3], [-1, 6]), P('e^x', 'b', { dash: true }), P('e^(-x)')] },
    { s: R`$y = e^{-x}$ is $e^x$ seen in a mirror: it decreases, still passes through $(0, 1)$, and tends to 0 on the right.|$y = e^{-x}$ est $e^x$ vue dans un miroir : elle décroît, passe toujours par $(0, 1)$ et tend vers 0 à droite.|$y = e^{-x}$ es $e^x$ en un espejo: decrece, sigue pasando por $(0, 1)$ y tiende a 0 a la derecha.|減少し、$(0, 1)$ を通る。|递减，仍过 $(0, 1)$。`,
      a: [Y(R`e^x \to e^{-x}`)] },
    { a: [F(R`y = x^3 + x^2`)],
      ex: { k: 'expr', f: '-x^3+x^2', q: R`Reflect the graph of $y = x^3 + x^2$ in the $y$-axis. Write $y = \dots$|Faites la symétrie du graphe de $y = x^3 + x^2$ par rapport à l’axe des $y$. Écrivez $y = \dots$|Refleja la gráfica de $y = x^3 + x^2$ respecto al eje $y$. Escribe $y = \dots$|$y = x^3 + x^2$ を $y$ 軸に関して対称移動した式を書け。|把 $y = x^3 + x^2$ 关于 $y$ 轴对称，写出 $y = \dots$`, sol: [R`y = (-x)^3 + (-x)^2`, R`= -x^3 + x^2`] } });

  TR('|f(x)|', 'Absolute value outside: |f(x)|, folded up|Valeur absolue extérieure : on replie vers le haut|Valor absoluto fuera: se refleja hacia arriba|外側の絶対値：下の部分を折り返す|外层绝对值：下方翻折向上'.replace(/\|f\(x\)\|, /, '∣f(x)∣, '),
    { s: R`$\lvert f(x)\rvert$ keeps the parts of the graph above the $x$-axis and flips the parts below it upwards. The result is never negative and has corners where $f$ crosses the axis.|$\lvert f(x)\rvert$ garde les parties du graphe au-dessus de l’axe des $x$ et replie vers le haut celles qui sont dessous. Le résultat n’est jamais négatif et a des angles là où $f$ coupe l’axe.|$\lvert f(x)\rvert$ conserva las partes de la gráfica sobre el eje $x$ y refleja hacia arriba las que están debajo. El resultado nunca es negativo y tiene picos donde $f$ corta el eje.|$\lvert f(x)\rvert$ は $x$ 軸より上はそのまま、下の部分を上へ折り返す。負にならず、$f$ が軸と交わる点で角ができる。|$\lvert f(x)\rvert$ 保留 $x$ 轴上方部分，把下方部分翻折向上。结果非负，并在 $f$ 穿过 $x$ 轴处出现尖角。`,
      a: [Y(R`y = \lvert f(x)\rvert`), AX([-4, 4], [-5, 6]), P('x^2-4', 'b', { dash: true }), P('abs(x^2-4)')] },
    { s: R`$y = \lvert x^2 - 4\rvert$: between $-2$ and $2$ the parabola dipped to $-4$; folded up, it peaks at $(0, 4)$.|$y = \lvert x^2 - 4\rvert$ : entre $-2$ et $2$ la parabole descendait à $-4$ ; repliée, elle culmine en $(0, 4)$.|$y = \lvert x^2 - 4\rvert$: entre $-2$ y $2$ la parábola bajaba a $-4$; reflejada, alcanza $(0, 4)$.|$-2$〜$2$ の部分が折り返され $(0, 4)$ に。|$-2$ 到 $2$ 之间翻折，最高点 $(0, 4)$。`,
      a: [Y(R`(0, -4) \to (0, 4)`), AX([-4, 4], [-5, 6]), P('abs(x^2-4)'), ['pt', 0, 4, '(0, 4)', { c: 'o' }]] },
    { s: TRY, a: [F(R`y = \lvert x^2 - 4\rvert`)],
      ex: { k: 'val', v: '3', q: R`Evaluate $y = \lvert x^2 - 4\rvert$ at $x = 1$.|Calculez $y = \lvert x^2 - 4\rvert$ en $x = 1$.|Calcula $y = \lvert x^2 - 4\rvert$ en $x = 1$.|$y = \lvert x^2 - 4\rvert$ の $x = 1$ での値を求めよ。|求 $y = \lvert x^2 - 4\rvert$ 在 $x = 1$ 处的值。`, sol: [R`1 - 4 = -3`, R`\lvert -3\rvert = 3`] } });

  TR('f(|x|)', 'Absolute value inside: keep the right half and mirror it|Valeur absolue intérieure : on garde la droite et on la recopie|Valor absoluto dentro: se conserva la derecha y se refleja|内側の絶対値：右半分を残して左に写す|内层绝对值：保留右半边并镜像到左边',
    { s: R`In $f(\lvert x\rvert)$ the input is never negative, so the left half of the graph is thrown away and replaced by a mirror copy of the right half. The result is always an even function.|Dans $f(\lvert x\rvert)$ l’entrée n’est jamais négative : la moitié gauche du graphe disparaît, remplacée par le symétrique de la moitié droite. Le résultat est toujours une fonction paire.|En $f(\lvert x\rvert)$ la entrada nunca es negativa: la mitad izquierda de la gráfica se descarta y se sustituye por una copia reflejada de la derecha. El resultado siempre es par.|$f(\lvert x\rvert)$ では入力が負にならないので、左半分は捨てて右半分の鏡像に置き換える。結果は常に偶関数。|$f(\lvert x\rvert)$ 中输入不为负，所以图像左半边被丢弃，换成右半边的镜像。结果总是偶函数。`,
      a: [Y(R`y = f(\lvert x\rvert)`), AX([-5, 5], [-5, 5]), P('x^2-4x', 'b', { dash: true }), P('x^2-4abs(x)')] },
    { s: R`$f(x) = x^2 - 4x$ has its vertex at $(2, -4)$; $f(\lvert x\rvert) = x^2 - 4\lvert x\rvert$ has two, at $(\pm 2, -4)$ — a “W” shape.|$f(x) = x^2 - 4x$ a son sommet en $(2, -4)$ ; $f(\lvert x\rvert)$ en a deux, en $(\pm 2, -4)$ — une forme en « W ».|$f(x) = x^2 - 4x$ tiene el vértice en $(2, -4)$; $f(\lvert x\rvert)$ tiene dos, en $(\pm 2, -4)$: forma de «W».|頂点が $(\pm 2, -4)$ の W 字型。|两个顶点 $(\pm 2, -4)$，呈 W 形。`,
      a: [Y(R`(2, -4)\ \text{and}\ (-2, -4)`), AX([-5, 5], [-5, 5]), P('x^2-4abs(x)'), ['pt', -2, -4, '', { c: 'o' }], ['pt', 2, -4, '', { c: 'o' }]] },
    { s: TRY, a: [F(R`f(x) = x^2 - 4x`)],
      ex: { k: 'val', v: '-3', q: R`$f(x) = x^2 - 4x$. Evaluate $f(\lvert x\rvert)$ at $x = -1$.|$f(x) = x^2 - 4x$. Calculez $f(\lvert x\rvert)$ en $x = -1$.|$f(x) = x^2 - 4x$. Calcula $f(\lvert x\rvert)$ en $x = -1$.|$f(x) = x^2 - 4x$。$x = -1$ での $f(\lvert x\rvert)$ を求めよ。|$f(x) = x^2 - 4x$，求 $x = -1$ 时 $f(\lvert x\rvert)$ 的值。`, sol: [R`f(\lvert -1\rvert) = f(1)`, R`= 1 - 4 = -3`] } });

  lesson('Transformations of graphs/Order of operations', 'Several transformations in order|Plusieurs transformations dans l’ordre|Varias transformaciones en orden|変形の順序|多个变换的顺序',
    { s: R`For $y = a\,f\big(b(x - h)\big) + k$, work from the inside out: squeeze by $b$, shift by $h$ horizontally, stretch by $a$ vertically, and finally shift by $k$ vertically. For a parabola $a(x - h)^2 + k$ the vertex simply goes to $(h, k)$.|Pour $y = a\,f\big(b(x - h)\big) + k$, on part de l’intérieur : contraction de $b$, translation de $h$ horizontalement, dilatation de $a$ verticalement, puis translation de $k$ verticalement. Pour une parabole $a(x - h)^2 + k$, le sommet va simplement en $(h, k)$.|Para $y = a\,f\big(b(x - h)\big) + k$, trabaja de dentro hacia fuera: comprime por $b$, traslada $h$ en horizontal, dilata por $a$ en vertical y por último traslada $k$ en vertical. Para una parábola $a(x - h)^2 + k$ el vértice va a $(h, k)$.|$y = a\,f\big(b(x - h)\big) + k$ は内側から：$b$ で縮小、横に $h$ 移動、縦に $a$ 倍、最後に縦に $k$ 移動。放物線 $a(x - h)^2 + k$ なら頂点は $(h, k)$。|对 $y = a\,f\big(b(x - h)\big) + k$ 由内向外：按 $b$ 压缩，水平平移 $h$，纵向伸缩 $a$，最后竖直平移 $k$。抛物线 $a(x - h)^2 + k$ 的顶点就到 $(h, k)$。`,
      a: [Y(R`y = a\,f\big(b(x - h)\big) + k`), AX([-3, 4], [-1, 8]), P('x^2', 'b', { dash: true }), P('2(x-1)^2+3')] },
    { s: R`$y = 2(x - 1)^2 + 3$ from $y = x^2$: right 1, stretch × 2, up 3. Vertex $(1, 3)$, and the parabola is narrower.|$y = 2(x - 1)^2 + 3$ à partir de $y = x^2$ : droite 1, dilatation × 2, haut 3. Sommet $(1, 3)$, parabole plus étroite.|$y = 2(x - 1)^2 + 3$ desde $y = x^2$: derecha 1, dilatación × 2, arriba 3. Vértice $(1, 3)$ y parábola más estrecha.|右 1、縦 2 倍、上 3：頂点 $(1, 3)$。|右移 1，纵向 2 倍，上移 3：顶点 $(1, 3)$。`,
      a: [F(R`x^2 \to (x - 1)^2 \to 2(x - 1)^2 \to 2(x - 1)^2 + 3`, { s: 22 }), Y(R`\text{vertex } (1, 3)`), AX([-3, 4], [-1, 8]), P('2(x-1)^2+3'), ['pt', 1, 3, '(1, 3)', { c: 'o' }]] },
    { s: 'Type the vertex as (x, y) and check. Each hint writes the next line of the solution.|Tapez le sommet sous la forme (x, y) et vérifiez. Chaque indice écrit la ligne suivante.|Escribe el vértice como (x, y) y comprueba. Cada pista escribe la siguiente línea.|頂点を (x, y) の形で入力して確かめよう。|以 (x, y) 形式输入顶点并检查。', a: [F(R`y = -(x + 2)^2 + 5`)],
      ex: { k: 'pt', v: [-2, 5], q: R`Find the vertex of $y = -(x + 2)^2 + 5$.|Trouvez le sommet de $y = -(x + 2)^2 + 5$.|Halla el vértice de $y = -(x + 2)^2 + 5$.|$y = -(x + 2)^2 + 5$ の頂点を求めよ。|求 $y = -(x + 2)^2 + 5$ 的顶点。`, sol: [R`h = -2,\ k = 5\ (\text{flipped by } a = -1)`, R`(-2,\ 5)`] } });

  // =============================== Basic graphs ===============================
  lesson('Basic graphs/Linear and quadratic', 'Lines and parabolas|Droites et paraboles|Rectas y parábolas|直線と放物線|直线与抛物线',
    { s: R`A line is fixed by its slope $m$ (rise over run) and its intercept $b$. A parabola $a(x - h)^2 + k$ has vertex $(h, k)$; it opens up when $a > 0$ and down when $a < 0$.|Une droite est fixée par sa pente $m$ (variation de $y$ sur variation de $x$) et son ordonnée à l’origine $b$. Une parabole $a(x - h)^2 + k$ a pour sommet $(h, k)$ ; elle est tournée vers le haut si $a > 0$, vers le bas si $a < 0$.|Una recta queda fijada por su pendiente $m$ (subida entre avance) y su ordenada en el origen $b$. Una parábola $a(x - h)^2 + k$ tiene vértice $(h, k)$; abre hacia arriba si $a > 0$ y hacia abajo si $a < 0$.|直線は傾き $m$（縦の変化 ÷ 横の変化）と切片 $b$ で決まる。放物線 $a(x - h)^2 + k$ の頂点は $(h, k)$、$a > 0$ で上に開き $a < 0$ で下に開く。|直线由斜率 $m$（纵向变化除以横向变化）和截距 $b$ 确定。抛物线 $a(x - h)^2 + k$ 顶点为 $(h, k)$；$a > 0$ 开口向上，$a < 0$ 开口向下。`,
      a: [Y(R`y = mx + b,\qquad y = a(x - h)^2 + k`), AX([-2, 5], [-3, 9]), P('3x-1', 'b'), P('(x-2)^2-1'), ['pt', 1, 2, '', { c: 'o' }], ['pt', 3, 8, '', { c: 'o' }]] },
    { s: R`The line through $(1, 2)$ and $(3, 8)$: $m = \tfrac{8 - 2}{3 - 1} = 3$, then $2 = 3\cdot 1 + b$ gives $b = -1$: $y = 3x - 1$.|La droite par $(1, 2)$ et $(3, 8)$ : $m = 3$, puis $b = -1$ : $y = 3x - 1$.|La recta por $(1, 2)$ y $(3, 8)$: $m = 3$ y luego $b = -1$: $y = 3x - 1$.|$m = 3$, $b = -1$。|$m = 3$，$b = -1$。`,
      a: [F(R`m = \frac{8 - 2}{3 - 1} = 3`), Y(R`y = 3x - 1`)] },
    { a: [F(R`(-1, 4),\quad (2, -2)`)],
      ex: { k: 'val', v: '-2', q: R`Find the slope of the line through $(-1, 4)$ and $(2, -2)$.|Trouvez la pente de la droite passant par $(-1, 4)$ et $(2, -2)$.|Halla la pendiente de la recta que pasa por $(-1, 4)$ y $(2, -2)$.|$(-1, 4)$ と $(2, -2)$ を通る直線の傾きを求めよ。|求过 $(-1, 4)$ 与 $(2, -2)$ 的直线斜率。`, sol: [R`m = \frac{-2 - 4}{2 - (-1)}`, R`= \frac{-6}{3} = -2`] } });

  lesson('Basic graphs/Exponential', 'Exponential graphs|Graphes exponentiels|Gráficas exponenciales|指数関数のグラフ|指数函数图像',
    { s: R`$a^x$ (with $a > 0$) passes through $(0, 1)$ because $a^0 = 1$, is always positive, and has the $x$-axis as an asymptote on one side. It grows when $a > 1$ and decays when $0 < a < 1$. A factor in front, $c\,a^x$, sets the starting value.|$a^x$ ($a > 0$) passe par $(0, 1)$ car $a^0 = 1$, est toujours positive et a l’axe des $x$ comme asymptote d’un côté. Elle croît si $a > 1$, décroît si $0 < a < 1$. Un facteur devant, $c\,a^x$, fixe la valeur de départ.|$a^x$ (con $a > 0$) pasa por $(0, 1)$ porque $a^0 = 1$, siempre es positiva y tiene el eje $x$ como asíntota por un lado. Crece si $a > 1$ y decrece si $0 < a < 1$. Un factor delante, $c\,a^x$, fija el valor inicial.|$a^x$（$a > 0$）は $a^0 = 1$ より $(0, 1)$ を通り、常に正で片側に $x$ 軸の漸近線。$a > 1$ で増加、$0 < a < 1$ で減少。前の係数 $c\,a^x$ は初期値。|$a^x$（$a > 0$）因 $a^0 = 1$ 过 $(0, 1)$，恒正，一侧以 $x$ 轴为渐近线。$a > 1$ 递增，$0 < a < 1$ 递减。前面的系数 $c\,a^x$ 决定初始值。`,
      a: [Y(R`y = a^x:\ (0, 1),\quad y > 0`), AX([-3, 3], [-0.5, 6]), P('2^x'), P('0.5^x', 'b'), ['pt', 0, 1, '(0, 1)', { c: 'o' }]] },
    { s: R`$y = 3\cdot 2^x$ starts at 3 and doubles every unit: 3, 6, 12, 24…|$y = 3\cdot 2^x$ part de 3 et double à chaque unité : 3, 6, 12, 24…|$y = 3\cdot 2^x$ empieza en 3 y se duplica cada unidad: 3, 6, 12, 24…|3 から始まり 1 ごとに 2 倍。|从 3 开始，每单位翻倍。`,
      a: [Y(R`3\cdot 2^0 = 3,\ 3\cdot 2^1 = 6,\ 3\cdot 2^2 = 12`, { s: 22 }), AX([-2, 3], [-1, 26]), P('3*2^x')] },
    { a: [F(R`y = c\cdot b^x:\ (0, 5),\ (1, 15)`)],
      ex: { k: 'val', v: '3', q: R`$y = c\cdot b^x$ passes through $(0, 5)$ and $(1, 15)$. Find $b$.|$y = c\cdot b^x$ passe par $(0, 5)$ et $(1, 15)$. Trouvez $b$.|$y = c\cdot b^x$ pasa por $(0, 5)$ y $(1, 15)$. Halla $b$.|$y = c\cdot b^x$ が $(0, 5)$, $(1, 15)$ を通る。$b$ を求めよ。|$y = c\cdot b^x$ 过 $(0, 5)$ 与 $(1, 15)$，求 $b$。`, sol: [R`c = 5`, R`5b = 15 \Rightarrow b = 3`] } });

  lesson('Basic graphs/Logarithm', 'Logarithmic graphs|Graphes logarithmiques|Gráficas logarítmicas|対数関数のグラフ|对数函数图像',
    { s: R`$\log_a x$ is the inverse of $a^x$: it passes through $(1, 0)$, is defined only for $x > 0$, and has the $y$-axis as asymptote. It answers “to what power must I raise $a$ to get $x$?”.|$\log_a x$ est la réciproque de $a^x$ : il passe par $(1, 0)$, n’est défini que pour $x > 0$ et a l’axe des $y$ comme asymptote. Il répond à « à quelle puissance élever $a$ pour obtenir $x$ ? ».|$\log_a x$ es la inversa de $a^x$: pasa por $(1, 0)$, solo está definido para $x > 0$ y tiene el eje $y$ como asíntota. Responde a «¿a qué potencia elevo $a$ para obtener $x$?».|$\log_a x$ は $a^x$ の逆関数：$(1, 0)$ を通り、$x > 0$ でのみ定義、$y$ 軸が漸近線。「$a$ を何乗すれば $x$ か」に答える。|$\log_a x$ 是 $a^x$ 的反函数：过 $(1, 0)$，只在 $x > 0$ 有定义，以 $y$ 轴为渐近线。它回答“$a$ 的几次方等于 $x$？”`,
      a: [Y(R`y = \log_a x:\ (1, 0),\quad x > 0`), AX([-1, 9], [-3, 4]), P('log(x)/log(2)'), ['pt', 1, 0, '(1, 0)', { c: 'o' }], ['pt', 8, 3, '(8, 3)', { c: 'b' }]] },
    { s: R`$\log_2 8 = 3$ because $2^3 = 8$ — the blue point. $\log_2 \tfrac12 = -1$ because $2^{-1} = \tfrac12$.|$\log_2 8 = 3$ car $2^3 = 8$ — le point bleu. $\log_2 \tfrac12 = -1$ car $2^{-1} = \tfrac12$.|$\log_2 8 = 3$ porque $2^3 = 8$, el punto azul. $\log_2 \tfrac12 = -1$ porque $2^{-1} = \tfrac12$.|$\log_2 8 = 3$、$\log_2 \tfrac12 = -1$。|$\log_2 8 = 3$，$\log_2 \tfrac12 = -1$。`,
      a: [F(R`\log_2 8 = 3 \iff 2^3 = 8`), Y(R`\log_2\tfrac12 = -1`)] },
    { a: [F(R`\log_3 x = 4`)],
      ex: { k: 'val', v: '81', q: R`Solve $\log_3 x = 4$.|Résolvez $\log_3 x = 4$.|Resuelve $\log_3 x = 4$.|$\log_3 x = 4$ を解け。|解 $\log_3 x = 4$。`, sol: [R`x = 3^4`, R`= 81`] } });

  lesson('Basic graphs/Rational (hyperbola)', 'Rational functions (hyperbolas)|Fonctions homographiques (hyperboles)|Funciones racionales (hipérbolas)|分数関数（双曲線）|分式函数（双曲线）',
    { s: R`$y = \tfrac{ax + b}{cx + d}$ is a hyperbola. The vertical asymptote is where the denominator vanishes, $x = -\tfrac dc$; for large $\lvert x\rvert$ only the leading terms matter, so $y \to \tfrac ac$, the horizontal asymptote.|$y = \tfrac{ax + b}{cx + d}$ est une hyperbole. L’asymptote verticale est là où le dénominateur s’annule, $x = -\tfrac dc$ ; pour $\lvert x\rvert$ grand seuls les termes dominants comptent, donc $y \to \tfrac ac$, l’asymptote horizontale.|$y = \tfrac{ax + b}{cx + d}$ es una hipérbola. La asíntota vertical está donde se anula el denominador, $x = -\tfrac dc$; para $\lvert x\rvert$ grande solo importan los términos principales, así que $y \to \tfrac ac$, la asíntota horizontal.|$y = \tfrac{ax + b}{cx + d}$ は双曲線。分母が 0 の $x = -\tfrac dc$ が垂直漸近線、$\lvert x\rvert$ が大きいと最高次だけが効き $y \to \tfrac ac$（水平漸近線）。|$y = \tfrac{ax + b}{cx + d}$ 是双曲线。分母为零处 $x = -\tfrac dc$ 是竖直渐近线；$\lvert x\rvert$ 很大时只看首项，$y \to \tfrac ac$，即水平渐近线。`,
      a: [Y(R`x = -\frac dc,\qquad y = \frac ac`), AX([-4, 10], [-6, 10]), P('(2x+1)/(x-3)'), VL(3, -6, 10), D('2', 'g')] },
    { s: R`$y = \tfrac{2x + 1}{x - 3}$: vertical asymptote $x = 3$, horizontal asymptote $y = \tfrac21 = 2$.|$y = \tfrac{2x + 1}{x - 3}$ : asymptotes $x = 3$ et $y = 2$.|$y = \tfrac{2x + 1}{x - 3}$: asíntotas $x = 3$ e $y = 2$.|漸近線 $x = 3$, $y = 2$。|渐近线 $x = 3$，$y = 2$。`,
      a: [F(R`x - 3 = 0 \Rightarrow x = 3`), Y(R`y \to \frac21 = 2`)] },
    { a: [F(R`y = \frac{6x - 1}{2x + 5}`)],
      ex: { k: 'val', v: '3', q: R`Find the horizontal asymptote $y = c$ of $y = \dfrac{6x - 1}{2x + 5}$.|Trouvez l’asymptote horizontale $y = c$ de $y = \dfrac{6x - 1}{2x + 5}$.|Halla la asíntota horizontal $y = c$ de $y = \dfrac{6x - 1}{2x + 5}$.|$y = \dfrac{6x - 1}{2x + 5}$ の水平漸近線 $y = c$ を求めよ。|求 $y = \dfrac{6x - 1}{2x + 5}$ 的水平渐近线 $y = c$。`, sol: [R`c = \frac{6}{2}`, R`= 3`] } });

  lesson('Basic graphs/Power functions', 'Power functions|Fonctions puissances|Funciones potencia|べき関数|幂函数',
    { s: R`Recognise the shapes: $x^2$ (U), $x^3$ (S through the origin), $\sqrt x$ (half a sideways parabola, from $(0, 0)$), $\tfrac1x$ (hyperbola in two quadrants), $\lvert x\rvert$ (V). All except $\tfrac1x$ pass through $(0, 0)$, and all pass through $(1, 1)$.|Reconnaître les formes : $x^2$ (U), $x^3$ (S passant par l’origine), $\sqrt x$ (demi-parabole couchée, depuis $(0, 0)$), $\tfrac1x$ (hyperbole dans deux quadrants), $\lvert x\rvert$ (V). Toutes sauf $\tfrac1x$ passent par $(0, 0)$, et toutes par $(1, 1)$.|Reconoce las formas: $x^2$ (U), $x^3$ (S por el origen), $\sqrt x$ (media parábola tumbada, desde $(0, 0)$), $\tfrac1x$ (hipérbola en dos cuadrantes), $\lvert x\rvert$ (V). Todas salvo $\tfrac1x$ pasan por $(0, 0)$, y todas por $(1, 1)$.|形を覚える：$x^2$（U）、$x^3$（原点を通る S）、$\sqrt x$（横向き放物線の半分）、$\tfrac1x$（2 象限の双曲線）、$\lvert x\rvert$（V）。$\tfrac1x$ 以外は $(0, 0)$ を、すべて $(1, 1)$ を通る。|认识形状：$x^2$（U 形）、$x^3$（过原点的 S 形）、$\sqrt x$（横放抛物线的一半）、$\tfrac1x$（两象限的双曲线）、$\lvert x\rvert$（V 形）。除 $\tfrac1x$ 外都过 $(0, 0)$，全部过 $(1, 1)$。`,
      a: [Y(R`x^n,\ \sqrt x,\ \frac1x,\ \lvert x\rvert`), AX([-3, 3], [-3, 3]), P('x^3', 'b'), P('sqrt(x)', 'y'), P('1/x', 'p'), P('abs(x)', 'g'), ['pt', 1, 1, '(1, 1)', { c: 'o' }]] },
    { s: R`On $(0, 1)$, $x^3 < x^2 < x < \sqrt x$; beyond 1 the order reverses. The curves all cross at $(1, 1)$.|Sur $]0, 1[$, $x^3 < x^2 < x < \sqrt x$ ; au-delà de 1 l’ordre s’inverse. Les courbes se croisent en $(1, 1)$.|En $(0, 1)$, $x^3 < x^2 < x < \sqrt x$; pasado 1 el orden se invierte. Las curvas se cruzan en $(1, 1)$.|$(0, 1)$ では $x^3 < x^2 < x < \sqrt x$、1 を超えると逆。|在 $(0, 1)$ 上 $x^3 < x^2 < x < \sqrt x$，超过 1 后顺序反转。`,
      a: [Y(R`0 < x < 1:\ x^3 < x^2 < x < \sqrt x`), AX([0, 1.6], [0, 1.6]), P('x^3', 'b'), P('x^2', 'p'), P('x', 'g'), P('sqrt(x)')] },
    { a: [F(R`\frac1x = x,\quad x > 0`)],
      ex: { k: 'val', v: '1', q: R`For which $x > 0$ do the graphs of $y = \tfrac1x$ and $y = x$ meet?|Pour quel $x > 0$ les graphes de $y = \tfrac1x$ et $y = x$ se coupent-ils ?|¿Para qué $x > 0$ se cortan las gráficas de $y = \tfrac1x$ e $y = x$?|$x > 0$ で $y = \tfrac1x$ と $y = x$ が交わる $x$ は？|$x > 0$ 时 $y = \tfrac1x$ 与 $y = x$ 在何处相交？`, sol: [R`x^2 = 1`, R`x = 1`] } });

  lesson('Basic graphs/Piecewise functions', 'Piecewise functions|Fonctions définies par morceaux|Funciones definidas a trozos|区分的に定義された関数|分段函数',
    { s: R`Different formulas on different intervals. To evaluate, first find which piece the input belongs to. To make the graph continuous at the switch $x = a$, both pieces must give the same value there.|Des formules différentes sur des intervalles différents. Pour calculer, on cherche d’abord à quel morceau appartient l’entrée. Pour un graphe continu au raccord $x = a$, les deux morceaux doivent y donner la même valeur.|Fórmulas distintas en intervalos distintos. Para evaluar, primero mira a qué trozo pertenece la entrada. Para que la gráfica sea continua en el cambio $x = a$, ambos trozos deben dar ahí el mismo valor.|区間ごとに違う式。値を求めるにはまず入力がどの区間か調べる。切り替え点 $x = a$ で連続にするには両方の式が同じ値を与えること。|不同区间用不同公式。求值时先看输入属于哪一段。要在分界点 $x = a$ 连续，两段在那里的值必须相同。`,
      a: [Y(R`f(x) = \begin{cases} g(x) & x < a\\ h(x) & x \ge a\end{cases}`), ['ax', { xw: [-3, 5], yw: [-3, 4] }], ['ln', -3, -2, 1, 2, { c: 'y' }], ['ln', 1, 2, 5, -2, { c: 'b' }], ['pt', 1, 2, '(1, 2)', { c: 'o' }]] },
    { s: R`$f(x) = x + 1$ for $x < 1$ and $3 - x$ for $x \ge 1$: both give 2 at $x = 1$, so the two lines meet in a peak at $(1, 2)$.|$f(x) = x + 1$ pour $x < 1$ et $3 - x$ pour $x \ge 1$ : les deux donnent 2 en $x = 1$ : les droites se rejoignent en $(1, 2)$.|$f(x) = x + 1$ para $x < 1$ y $3 - x$ para $x \ge 1$: ambas dan 2 en $x = 1$, así que se unen en $(1, 2)$.|どちらも $x = 1$ で 2：$(1, 2)$ でつながる。|两段在 $x = 1$ 都为 2，于 $(1, 2)$ 相接。`,
      a: [F(R`1 + 1 = 2 = 3 - 1`), Y(R`\text{continuous at } (1, 2)`)] },
    { a: [F(R`f(x) = \begin{cases} ax & x < 2\\ x^2 - 1 & x \ge 2\end{cases}`)],
      ex: { k: 'val', v: '1.5', q: R`Find $a$ so that $f(x) = ax$ for $x < 2$ and $f(x) = x^2 - 1$ for $x \ge 2$ is continuous.|Trouvez $a$ pour que $f(x) = ax$ si $x < 2$ et $f(x) = x^2 - 1$ si $x \ge 2$ soit continue.|Halla $a$ para que $f(x) = ax$ si $x < 2$ y $f(x) = x^2 - 1$ si $x \ge 2$ sea continua.|$x < 2$ で $ax$、$x \ge 2$ で $x^2 - 1$ の関数が連続になる $a$ を求めよ。|求 $a$ 使 $x < 2$ 时 $f(x) = ax$、$x \ge 2$ 时 $f(x) = x^2 - 1$ 连续。`, sol: [R`2a = 2^2 - 1 = 3`, R`a = \frac32`] } });

  // =============================== Zeros and intersections ===============================
  lesson('Zeros and intersections/Zeros', 'Zeros of a function|Zéros d’une fonction|Ceros de una función|関数の零点|函数的零点',
    { s: R`A zero is an $x$ with $f(x) = 0$: where the graph meets the $x$-axis. To find them, factor if you can — a product is zero when one factor is.|Un zéro est un $x$ tel que $f(x) = 0$ : là où le graphe coupe l’axe des $x$. Pour les trouver, on factorise si possible — un produit est nul quand un facteur l’est.|Un cero es un $x$ con $f(x) = 0$: donde la gráfica corta el eje $x$. Para hallarlos, factoriza si puedes: un producto es cero cuando lo es un factor.|零点は $f(x) = 0$ となる $x$：グラフと $x$ 軸の交点。できれば因数分解（積が 0 ⇔ どれかの因数が 0）。|零点是使 $f(x) = 0$ 的 $x$：图像与 $x$ 轴的交点。能因式分解就分解——乘积为零当且仅当某个因子为零。`,
      a: [Y(R`f(x) = 0 \iff (x, 0)\ \text{on the graph}`, { s: 24 }), AX([-4, 5], [-7, 6]), P('x^2-x-6'), ['pt', -2, 0, '−2', { c: 'o' }], ['pt', 3, 0, '3', { c: 'o' }]] },
    { s: R`$x^2 - x - 6 = (x - 3)(x + 2) = 0$, so $x = 3$ or $x = -2$.|$x^2 - x - 6 = (x - 3)(x + 2) = 0$, donc $x = 3$ ou $x = -2$.|$x^2 - x - 6 = (x - 3)(x + 2) = 0$, así que $x = 3$ o $x = -2$.|$x = 3, -2$。|$x = 3$ 或 $-2$。`,
      a: [F(R`x^2 - x - 6 = (x - 3)(x + 2)`), Y(R`x = 3,\quad x = -2`)] },
    { s: TRY_R, a: [F(R`f(x) = x^3 - 4x`), AX([-3, 3], [-5, 5]), P('x^3-4x')],
      ex: { k: 'roots', v: [-2, 0, 2], q: R`Find all zeros of $f(x) = x^3 - 4x$.|Trouvez tous les zéros de $f(x) = x^3 - 4x$.|Halla todos los ceros de $f(x) = x^3 - 4x$.|$f(x) = x^3 - 4x$ の零点をすべて求めよ。|求 $f(x) = x^3 - 4x$ 的所有零点。`, sol: [R`x(x^2 - 4) = x(x - 2)(x + 2)`, R`x = 0,\ \pm 2`] } });

  lesson('Zeros and intersections/Bolzano', 'Bolzano’s theorem|Théorème de Bolzano|Teorema de Bolzano|中間値の定理（ボルツァーノ）|零点存在定理',
    { s: R`A continuous function that is negative at one end of $[a, b]$ and positive at the other must cross zero in between. Halving the interval and keeping the half with a sign change (bisection) traps the zero as tightly as you like.|Une fonction continue négative à un bout de $[a, b]$ et positive à l’autre doit s’annuler entre les deux. En coupant l’intervalle en deux et en gardant la moitié où le signe change (dichotomie), on encadre le zéro aussi finement qu’on veut.|Una función continua negativa en un extremo de $[a, b]$ y positiva en el otro debe anularse entre medias. Partiendo el intervalo por la mitad y quedándose con la mitad donde cambia el signo (bisección) se acota el cero tanto como se quiera.|$[a, b]$ の一端で負、他端で正の連続関数は間で必ず 0 になる。区間を半分にし符号が変わる方を残す（二分法）と零点をいくらでも狭く挟める。|在 $[a, b]$ 一端为负、另一端为正的连续函数必在中间取零。把区间对半分，保留变号的一半（二分法），可以把零点夹得任意紧。`,
      a: [Y(R`f(a)\,f(b) < 0 \Rightarrow \exists\,c \in (a, b):\ f(c) = 0`, { s: 22 }), AX([-0.3, 1.3], [-1.3, 1.3]), P('x^3+x-1'), ['pt', 0, -1, 'f(0) < 0', { c: 'b' }], ['pt', 1, 1, 'f(1) > 0', { c: 'b' }]] },
    { s: R`$f(x) = x^3 + x - 1$: $f(0) = -1 < 0$ and $f(1) = 1 > 0$, so there is a zero in $(0, 1)$. $f(0.5) = -0.375 < 0$ moves it into $(0.5, 1)$.|$f(0) = -1 < 0$ et $f(1) = 1 > 0$ : un zéro dans $]0, 1[$. $f(0{,}5) = -0{,}375 < 0$ le place dans $]0{,}5 ; 1[$.|$f(0) = -1 < 0$ y $f(1) = 1 > 0$: hay un cero en $(0, 1)$. $f(0{,}5) = -0{,}375 < 0$ lo lleva a $(0{,}5;\ 1)$.|$f(0.5) = -0.375$ で $(0.5, 1)$ に。|$f(0.5) = -0.375$，零点在 $(0.5, 1)$。`,
      a: [F(R`f(0) = -1,\quad f(1) = 1`), Y(R`f(0.5) = -0.375 \Rightarrow c \in (0.5,\ 1)`)] },
    { a: [F(R`f(x) = x^3 + x - 1\ \text{on}\ [0, 1]`)],
      ex: { k: 'val', v: '0.625', q: R`Start from $[0, 1]$ and do two bisection steps for $f(x) = x^3 + x - 1$. What is the midpoint of the interval you are left with?|Partez de $[0, 1]$ et faites deux étapes de dichotomie pour $f(x) = x^3 + x - 1$. Quel est le milieu de l’intervalle obtenu ?|Parte de $[0, 1]$ y haz dos pasos de bisección para $f(x) = x^3 + x - 1$. ¿Cuál es el punto medio del intervalo que queda?|$f(x) = x^3 + x - 1$ について $[0, 1]$ から二分法を 2 回行う。残った区間の中点は？|对 $f(x) = x^3 + x - 1$ 从 $[0, 1]$ 开始做两次二分，剩下区间的中点是多少？`,
        sol: [R`f(0.5) < 0 \Rightarrow [0.5,\ 1]`, R`f(0.75) \approx 0.17 > 0 \Rightarrow [0.5,\ 0.75]`, R`\text{midpoint } 0.625`] } });

  lesson('Zeros and intersections/Number of solutions', 'Counting solutions with graphs|Compter les solutions avec des graphes|Contar soluciones con gráficas|グラフで解の個数を数える|用图像数解的个数',
    { s: R`An equation $f(x) = g(x)$ you cannot solve by algebra can still be understood: draw both graphs and count where they meet. Each intersection point is one solution; its $x$-coordinate is the value.|Une équation $f(x) = g(x)$ qu’on ne sait pas résoudre algébriquement peut quand même être comprise : on trace les deux graphes et on compte leurs points communs. Chaque point d’intersection est une solution ; son abscisse en est la valeur.|Una ecuación $f(x) = g(x)$ que no se resuelve con álgebra puede entenderse igualmente: dibuja ambas gráficas y cuenta dónde se cortan. Cada punto de corte es una solución; su abscisa es el valor.|代数で解けない $f(x) = g(x)$ も、両方のグラフを描いて交点を数えれば理解できる。交点 1 つが解 1 つで、その $x$ 座標が値。|代数解不出的方程 $f(x) = g(x)$ 也可以理解：画出两图像，数交点。每个交点是一个解，其横坐标就是解的值。`,
      a: [Y(R`f(x) = g(x) \iff y = f \cap y = g`, { s: 24 }), AX([-3, 3], [-1, 6]), P('e^x'), P('x+2', 'b')] },
    { s: R`$e^x = x + 2$: the exponential crosses the line twice — once near $x \approx -1.84$ and once near $x \approx 1.15$ — so there are 2 solutions.|$e^x = x + 2$ : l’exponentielle coupe la droite deux fois — vers $x \approx -1{,}84$ et $x \approx 1{,}15$ — donc 2 solutions.|$e^x = x + 2$: la exponencial corta la recta dos veces, cerca de $x \approx -1{,}84$ y de $x \approx 1{,}15$: 2 soluciones.|2 回交わるので解は 2 個。|交于两点，2 个解。`,
      a: [Y(R`2\ \text{solutions}`), AX([-3, 3], [-1, 6]), P('e^x'), P('x+2', 'b'), ['pt', -1.8414, 0.1586, '', { c: 'o' }], ['pt', 1.1462, 3.1462, '', { c: 'o' }]] },
    { a: [F(R`x^2 = 2^x`), AX([-2, 5], [-1, 18]), P('x^2'), P('2^x', 'b')],
      ex: { k: 'val', v: '3', q: R`How many real solutions does $x^2 = 2^x$ have?|Combien de solutions réelles a l’équation $x^2 = 2^x$ ?|¿Cuántas soluciones reales tiene $x^2 = 2^x$?|$x^2 = 2^x$ の実数解は何個か。|$x^2 = 2^x$ 有几个实数解？`, sol: [R`x = 2,\ x = 4\ \text{(check)}`, R`\text{one more for } x < 0\ (x \approx -0.77)`, R`3\ \text{solutions}`] } });

  Cheats.tutor('functions', L);
})();
